import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface KKMember {
  nama: string;
  nik: string;
  jenis_kelamin: string;
  tempat_lahir: string;
  tanggal_lahir: string;
  agama: string;
  pendidikan: string;
  jenis_pekerjaan: string;
  status_perkawinan: string;
  status_hubungan: string;
  kewarganegaraan: string;
  nama_ayah: string;
  nama_ibu: string;
}

export interface KKData {
  nomor_kk: string;
  alamat: string;
  rt_rw: string;
  kode_pos: string;
  desa_kelurahan: string;
  kecamatan: string;
  kabupaten_kota: string;
  provinsi: string;
  anggota_keluarga: KKMember[];
}

export enum AppState {
  IDLE = 'IDLE',
  SCANNING = 'SCANNING',
  REVIEWING = 'REVIEWING',
  SAVED = 'SAVED'
}

import { GoogleGenAI, Type } from "@google/genai";
import { KKData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const kkSchema = {
  type: Type.OBJECT,
  properties: {
    nomor_kk: { type: Type.STRING, description: "Nomor Kartu Keluarga" },
    alamat: { type: Type.STRING, description: "Alamat Lengkap" },
    rt_rw: { type: Type.STRING, description: "RT/RW" },
    kode_pos: { type: Type.STRING, description: "Kode Pos" },
    desa_kelurahan: { type: Type.STRING, description: "Desa atau Kelurahan" },
    kecamatan: { type: Type.STRING, description: "Kecamatan" },
    kabupaten_kota: { type: Type.STRING, description: "Kabupaten atau Kota" },
    provinsi: { type: Type.STRING, description: "Provinsi" },
    anggota_keluarga: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          nama: { type: Type.STRING },
          nik: { type: Type.STRING },
          jenis_kelamin: { type: Type.STRING },
          tempat_lahir: { type: Type.STRING },
          tanggal_lahir: { type: Type.STRING },
          agama: { type: Type.STRING },
          pendidikan: { type: Type.STRING },
          jenis_pekerjaan: { type: Type.STRING },
          status_perkawinan: { type: Type.STRING },
          status_hubungan: { type: Type.STRING },
          kewarganegaraan: { type: Type.STRING },
          nama_ayah: { type: Type.STRING },
          nama_ibu: { type: Type.STRING },
        },
      },
    },
  },
  required: ["nomor_kk", "anggota_keluarga"],
};

export const extractKKData = async (base64Image: string): Promise<KKData> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: [
        {
          parts: [
            {
              inlineData: {
                mimeType: "image/jpeg",
                data: base64Image.split(",")[1],
              },
            },
            {
              text: "Ekstrak data lengkap dari dokumen Kartu Keluarga ini ke dalam format JSON yang terstruktur sesuai skema. Pastikan NIK dan Nomor KK terbaca dengan benar. Jika data tidak ditemukan, biarkan string kosong.",
            },
          ],
        },
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: kkSchema,
      },
    });

    const text = response.text;
    if (!text) throw new Error("Gagal mengekstrak teks dari gambar.");

    return JSON.parse(text) as KKData;
  } catch (error) {
    console.error("Error in extractKKData:", error);
    throw error;
  }
};

import React, { useRef } from 'react';

interface FileUploadProps {
  onFileSelect: (base64: string) => void;
  isLoading: boolean;
}

const FileUpload: React.FC<FileUploadProps> = ({ onFileSelect, isLoading }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        onFileSelect(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="w-full max-w-2xl mx-auto">
      <div className="bg-white rounded-2xl shadow-sm border-2 border-dashed border-gray-300 p-8 text-center transition-all hover:border-indigo-400 hover:bg-indigo-50/30 group">
        <div className="flex flex-col items-center gap-4">
          <div className="w-16 h-16 bg-indigo-100 rounded-full flex items-center justify-center text-indigo-600 group-hover:scale-110 transition-transform">
            <i className="fa-solid fa-cloud-arrow-up text-3xl"></i>
          </div>
          <div>
            <h3 className="text-lg font-bold text-gray-900">Upload Foto Kartu Keluarga</h3>
            <p className="text-sm text-gray-500 mt-1">Pastikan seluruh bagian KK terlihat jelas dan cukup cahaya</p>
          </div>

          <div className="flex gap-3 mt-4 w-full sm:w-auto">
            <button 
              onClick={() => fileInputRef.current?.click()}
              disabled={isLoading}
              className="flex-1 sm:flex-none px-6 py-3 bg-indigo-600 text-white rounded-xl font-semibold shadow-md hover:bg-indigo-700 active:scale-95 transition-all disabled:opacity-50 disabled:pointer-events-none"
            >
              <i className="fa-solid fa-image mr-2"></i> Pilih File
            </button>
            <button 
              onClick={() => fileInputRef.current?.click()}
              disabled={isLoading}
              className="flex-1 sm:flex-none px-6 py-3 bg-white text-indigo-600 border border-indigo-200 rounded-xl font-semibold shadow-sm hover:bg-indigo-50 active:scale-95 transition-all disabled:opacity-50 disabled:pointer-events-none"
            >
              <i className="fa-solid fa-camera mr-2"></i> Ambil Foto
            </button>
          </div>

          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
            accept="image/*" 
            className="hidden" 
          />

          <div className="mt-4 flex items-center gap-6 text-xs text-gray-400 font-medium">
            <span className="flex items-center gap-1"><i className="fa-solid fa-check text-green-500"></i> JPG/PNG</span>
            <span className="flex items-center gap-1"><i className="fa-solid fa-check text-green-500"></i> Max 5MB</span>
            <span className="flex items-center gap-1"><i className="fa-solid fa-check text-green-500"></i> High Quality</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default FileUpload;

import React, { useState } from 'react';
import Header from './components/Header';
import FileUpload from './components/FileUpload';
import KKForm from './components/KKForm';
import SuccessState from './components/SuccessState';
import { extractKKData } from './services/geminiService';
import { AppState, KKData } from './types';

