                  <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-xl flex items-center justify-center mb-4">
                    <i className={`fa-solid ${item.icon} text-xl`}></i>
                  </div>
                  <h4 className="font-bold text-slate-900">{item.title}</h4>
                  <p className="text-sm text-slate-500 mt-2">{item.desc}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {state === AppState.SCANNING && (
          <div className="flex flex-col items-center justify-center py-20 animate-pulse">
            <div className="relative w-24 h-24 mb-8">
              <div className="absolute inset-0 border-4 border-indigo-200 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-indigo-600 rounded-full border-t-transparent animate-spin"></div>
              <i className="fa-solid fa-wand-magic-sparkles absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-indigo-600 text-3xl"></i>
            </div>
            <h3 className="text-2xl font-bold text-slate-900">Menganalisis Dokumen...</h3>
            <p className="text-slate-500 mt-2">AI sedang mengekstrak data dari Kartu Keluarga Anda.</p>
          </div>
        )}

        {state === AppState.REVIEWING && kkData && (
          <div className="max-w-5xl mx-auto animate-in fade-in slide-in-from-bottom-6 duration-500">
            <div className="flex items-center justify-between mb-6">
