          <h4 className="font-bold text-slate-900">Informasi Kepala Keluarga & Alamat</h4>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-1">
            <label className="text-xs font-bold text-slate-500 uppercase">Nomor Kartu Keluarga</label>
            <input 
              name="nomor_kk"
              value={formData.nomor_kk}
              onChange={handleHeaderChange}
              className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:bg-white outline-none transition-all font-mono tracking-wider"
              placeholder="16 digit nomor KK"
            />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold text-slate-500 uppercase">Alamat</label>
            <input 
              name="alamat"
              value={formData.alamat}
              onChange={handleHeaderChange}
              className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:bg-white outline-none transition-all"
