            </div>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-xs font-bold text-slate-500 uppercase">Kecamatan</label>
              <input 
                name="kecamatan"
                value={formData.kecamatan}
