                    name="tanggal_lahir"
                    value={member.tanggal_lahir}
                    onChange={(e) => handleMemberChange(index, e)}
                    className="w-24 px-3 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-sm"
                  />
