              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase">Pekerjaan</label>
                <input 
                  name="jenis_pekerjaan"
                  value={member.jenis_pekerjaan}
                  onChange={(e) => handleMemberChange(index, e)}
                  className="w-full px-3 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-sm"
                />
              </div>
            </div>
          </div>
        ))}
      </section>

      {/* Action Buttons */}
      <div className="flex flex-col sm:flex-row gap-4 pt-6 border-t border-slate-200">
        <button 
          onClick={() => onSave(formData)}
          disabled={isSaving}
          className="flex-1 bg-indigo-600 text-white px-8 py-4 rounded-2xl font-bold shadow-lg shadow-indigo-200 hover:bg-indigo-700 active:scale-[0.98] transition-all disabled:opacity-70 flex items-center justify-center gap-3"
        >
          {isSaving ? (
            <>
              <i className="fa-solid fa-circle-notch animate-spin"></i>
              Menyimpan ke Spreadsheet...
            </>
          ) : (
            <>
              <i className="fa-solid fa-cloud-arrow-up"></i>
              Simpan Data ke Spreadsheet
            </>
          )}
        </button>
      </div>
    </div>
  );
};

export default KKForm;

import React, { useState } from 'react';
import Header from './components/Header';
import FileUpload from './components/FileUpload';
import KKForm from './components/KKForm';
import SuccessState from './components/SuccessState';
import { extractKKData } from './services/geminiService';
import { AppState, KKData } from './types';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(AppState.IDLE);
  const [kkData, setKkData] = useState<KKData | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  const handleFileSelect = async (base64: string) => {
    setState(AppState.SCANNING);
    setError(null);
    try {
      const data = await extractKKData(base64);
      setKkData(data);
      setState(AppState.REVIEWING);
    } catch (err) {
      console.error(err);
      setError("Gagal membaca data KK. Pastikan gambar cukup terang, tidak blur, dan dokumen KK terlihat utuh.");
      setState(AppState.IDLE);
    }
  };

  const handleSave = async (finalData: KKData) => {
    setIsSaving(true);
    // Simulasi pengiriman data ke spreadsheet (misal: via Google Apps Script)
    try {
      await new Promise(resolve => setTimeout(resolve, 2000));
      console.log("Data berhasil disinkronisasi ke spreadsheet:", finalData);
      setIsSaving(false);
      setState(AppState.SAVED);
    } catch (err) {
      setError("Terjadi kesalahan saat menyimpan ke spreadsheet.");
      setIsSaving(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <Header />

      <main className="flex-grow container mx-auto px-4 py-8">
        {state === AppState.IDLE && (
