import React, { useState } from 'react';
import Header from './components/Header';
import FileUpload from './components/FileUpload';
import KKForm from './components/KKForm';
import SuccessState from './components/SuccessState';
import { extractKKData } from './services/geminiService';
import { AppState, KKData } from './types';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(AppState.IDLE);
  const [kkData, setKkData] = useState<KKData | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  const handleFileSelect = async (base64: string) => {
    setState(AppState.SCANNING);
    setError(null);
    try {
      const data = await extractKKData(base64);
      setKkData(data);
      setState(AppState.REVIEWING);
    } catch (err) {
      console.error(err);
      setError("Gagal membaca data KK. Pastikan gambar cukup terang, tidak blur, dan dokumen KK terlihat utuh.");
      setState(AppState.IDLE);
    }
  };

  const downloadCSV = (data: KKData) => {
    // Header untuk CSV
    const headers = ["Nomor KK", "Alamat", "RT_RW", "Kecamatan", "Kabupaten", "Nama Anggota", "NIK", "Hubungan", "Pekerjaan"];

    // Baris data (Satu baris per anggota keluarga)
    const rows = data.anggota_keluarga.map(m => [
      data.nomor_kk,
      data.alamat,
      data.rt_rw,
      data.kecamatan,
      data.kabupaten_kota,
      m.nama,
      m.nik,
      m.status_hubungan,
      m.jenis_pekerjaan
    ].map(val => `"${val}"`).join(","));

    const csvContent = [headers.join(","), ...rows].join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `Data_KK_${data.nomor_kk || 'Export'}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleSave = async (finalData: KKData) => {
    setIsSaving(true);
    try {
      // Simulasi delay proses
      await new Promise(resolve => setTimeout(resolve, 1500));

      // Jalankan fungsi download sebagai pengganti simpan ke database cloud
      downloadCSV(finalData);

      setIsSaving(false);
      setState(AppState.SAVED);
    } catch (err) {
      setError("Terjadi kesalahan saat memproses data.");
      setIsSaving(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <Header />

      <main className="flex-grow container mx-auto px-4 py-8">
        {state === AppState.IDLE && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
            <div className="text-center mb-10">
              <span className="inline-block px-4 py-1.5 mb-4 text-xs font-bold tracking-widest text-indigo-600 uppercase bg-indigo-50 rounded-full">
                AI Powered Data Entry
              </span>
              <h2 className="text-3xl font-extrabold text-slate-900 sm:text-4xl">Digitalisasi Data Keluarga</h2>
              <p className="mt-4 text-lg text-slate-600 max-w-2xl mx-auto">
                Efisienkan input data dengan teknologi OCR AI. Foto Kartu Keluarga Anda dan sistem akan otomatis membuatkan file spreadsheet untuk Anda.
              </p>
            </div>

            {error && (
              <div className="mb-6 max-w-2xl mx-auto p-4 bg-red-50 border-l-4 border-red-500 rounded-r-lg flex items-center gap-3 text-red-700 shadow-sm">
                <i className="fa-solid fa-circle-exclamation"></i>
                <span className="text-sm font-medium">{error}</span>
              </div>
            )}

            <FileUpload onFileSelect={handleFileSelect} isLoading={false} />

            <div className="mt-12 max-w-3xl mx-auto p-6 bg-white rounded-2xl border border-slate-200 shadow-sm">
              <h4 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                <i className="fa-solid fa-file-csv text-green-600"></i>
                Hasil Akhir:
              </h4>
              <p className="text-sm text-slate-600 leading-relaxed">
                Setelah verifikasi, data akan diunduh dalam format <strong>.CSV</strong>. Anda bisa langsung membukanya di <strong>Excel</strong> untuk dikelola lebih lanjut.
              </p>
            </div>
          </div>
        )}

        {state === AppState.SCANNING && (
          <div className="flex flex-col items-center justify-center py-20">
            <div className="relative w-32 h-32 mb-8">
              <div className="absolute inset-0 border-4 border-indigo-100 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-indigo-600 rounded-full border-t-transparent animate-spin"></div>
              <div className="absolute inset-4 bg-indigo-50 rounded-full flex items-center justify-center">
                <i className="fa-solid fa-brain text-indigo-600 text-3xl animate-pulse"></i>
              </div>
            </div>
            <h3 className="text-2xl font-bold text-slate-900">AI Sedang Memproses...</h3>
            <p className="text-slate-500 mt-2 text-center max-w-xs">
              Mengekstrak data dari foto dan menyusunnya ke tabel digital.
            </p>
          </div>
        )}

        {state === AppState.REVIEWING && kkData && (
          <div className="max-w-5xl mx-auto animate-in fade-in slide-in-from-bottom-6 duration-500">
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between mb-6 gap-4">
              <div>
                <h3 className="text-2xl font-bold text-slate-900">Verifikasi Data Hasil Scan</h3>
                <p className="text-slate-500">Pastikan NIK dan nama sudah benar sebelum diunduh ke CSV.</p>
              </div>
              <button 
                onClick={() => setState(AppState.IDLE)}
                className="px-4 py-2 text-sm font-semibold text-slate-600 hover:text-slate-900 bg-slate-100 hover:bg-slate-200 rounded-lg transition-colors flex items-center gap-2"
              >
