Tentu! Saya akan memandu Anda secara mendetail. Saya telah memperbarui aplikasi untuk **otomatis mengisi ID** yang Anda berikan, sehingga Anda tidak perlu mengetiknya lagi.

### 1. Persiapan Spreadsheet (Wajib)
Pastikan Spreadsheet Anda memiliki kolom yang sesuai. Silakan buat header di **Sheet1** pada baris pertama (A1 sampai W1) dengan urutan berikut agar rapi:

| No KK | Alamat | RT/RW | Desa | Kec | Kota | Prov | Pos | Nama | NIK | JK | Tpt Lahir | Tgl Lahir | Agama | Pend | Kerja | Kawin | Hub | Negara | Ayah | Ibu | Foto | Waktu |
| :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- |

---

### 2. Kode Google Apps Script
Ikuti langkah ini:
1. Buka Spreadsheet Anda (`1mIpV...`).
2. Klik **Extensions** -> **Apps Script**.
3. Hapus semua kode di `Code.gs`, lalu **Copy & Paste** kode di bawah ini:

```javascript
/**
 * Google Apps Script untuk KK-OCR Pro
 * Menerima data dari aplikasi React dan menyimpannya ke Spreadsheet & Drive
 */

function doPost(e) {
  try {
    var data = JSON.parse(e.postData.contents);
    var ssId = data.spreadsheet_id;
    var folderId = data.folder_id;
    var sheetName = "Sheet1"; // Nama sheet Anda

    var ss = SpreadsheetApp.openById(ssId);
    var sheet = ss.getSheetByName(sheetName);
    if (!sheet) sheet = ss.getSheets()[0];

    // --- PROSES SIMPAN GAMBAR KE DRIVE ---
    var imageUrl = "Tidak ada gambar";
    if (data.image_base64 && folderId) {
      try {
        var folder = DriveApp.getFolderById(folderId);
        var contentType = data.image_base64.substring(5, data.image_base64.indexOf(';'));
        var bytes = Utilities.base64Decode(data.image_base64.split(',')[1]);
        var blob = Utilities.newBlob(bytes, contentType, "KK_" + data.nomor_kk + "_" + new Date().getTime() + ".jpg");
        var file = folder.createFile(blob);
        file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
        imageUrl = file.getUrl();
      } catch (err) {
        imageUrl = "Error simpan gambar: " + err.toString();
      }
    }

    // --- SIMPAN DATA ANGGOTA KELUARGA ---
    var timestamp = new Date().toLocaleString("id-ID");

    // Looping setiap anggota keluarga yang dikirim
    data.anggota_keluarga.forEach(function(m) {
      sheet.appendRow([
        data.nomor_kk,
        data.alamat,
        data.rt_rw,
        data.desa_kelurahan,
        data.kecamatan,
        data.kabupaten_kota,
        data.provinsi,
        data.kode_pos,
        m.nama,
        m.nik,
        m.jenis_kelamin,
        m.tempat_lahir,
        m.tanggal_lahir,
        m.agama,
        m.pendidikan,
        m.jenis_pekerjaan,
        m.status_perkawinan,
        m.status_hubungan,
        m.kewarganegaraan,
        m.nama_ayah,
        m.nama_ibu,
        imageUrl,
        timestamp
      ]);
    });

    return ContentService.createTextOutput("Success").setMimeType(ContentService.MimeType.TEXT);
  } catch (error) {
    return ContentService.createTextOutput("Error: " + error.toString()).setMimeType(ContentService.MimeType.TEXT);
  }
}
