import React, { useRef, useState } from 'react';
import CameraCapture from './CameraCapture';

interface FileUploadProps {
  onFileSelect: (base64: string) => void;
  isLoading: boolean;
}

const FileUpload: React.FC<FileUploadProps> = ({ onFileSelect, isLoading }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [showCamera, setShowCamera] = useState(false);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        onFileSelect(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleCameraCapture = (base64: string) => {
    setShowCamera(false);
    onFileSelect(base64);
  };

  return (
    <div className="w-full max-w-2xl mx-auto">
      {showCamera && (
        <CameraCapture 
          onCapture={handleCameraCapture} 
          onClose={() => setShowCamera(false)} 
        />
      )}

      <div className="bg-white rounded-3xl shadow-sm border-2 border-dashed border-gray-200 p-10 text-center transition-all hover:border-indigo-400 hover:bg-indigo-50/30 group">
        <div className="flex flex-col items-center gap-6">
          <div className="w-20 h-20 bg-indigo-100 rounded-2xl flex items-center justify-center text-indigo-600 group-hover:rotate-6 transition-transform shadow-sm">
            <i className="fa-solid fa-file-invoice text-4xl"></i>
          </div>
          <div>
            <h3 className="text-2xl font-black text-gray-900 tracking-tight">Input Dokumen KK</h3>
            <p className="text-sm text-gray-500 mt-2 font-medium">Gunakan kamera untuk hasil maksimal atau upload dari galeri.</p>
          </div>

          <div className="flex flex-col sm:flex-row gap-4 mt-4 w-full justify-center">
            <button 
              onClick={() => setShowCamera(true)}
              disabled={isLoading}
              className="px-10 py-5 bg-indigo-600 text-white rounded-2xl font-black shadow-xl shadow-indigo-200 hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center gap-3 text-lg"
            >
              <i className="fa-solid fa-camera text-2xl"></i> Ambil Foto Kamera
            </button>
            <button 
              onClick={() => fileInputRef.current?.click()}
              disabled={isLoading}
              className="px-10 py-5 bg-white text-indigo-600 border-2 border-indigo-50 rounded-2xl font-black shadow-sm hover:bg-indigo-50 active:scale-95 transition-all flex items-center justify-center gap-3 text-lg"
            >
              <i className="fa-solid fa-images text-2xl"></i> Galeri Foto
            </button>
          </div>

          {/* Input Tersembunyi untuk Galeri saja */}
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
            accept="image/*" 
            className="hidden" 
          />

          <div className="mt-6 flex flex-wrap justify-center items-center gap-6 text-[10px] text-gray-400 font-black uppercase tracking-widest">
            <span className="flex items-center gap-2"><i className="fa-solid fa-bolt text-amber-400"></i> AI-OCR AKTIF</span>
