interface DatabaseViewProps {
  entries: SavedEntry[];
  isLoading?: boolean;
  hasError?: boolean;
  spreadsheetId: string;
  onRefresh: () => void;
  onBack: () => void;
}

const DatabaseView: React.FC<DatabaseViewProps> = ({ entries, isLoading, hasError, spreadsheetId, onRefresh, onBack }) => {
  const [search, setSearch] = useState("");
  const [showSetup, setShowSetup] = useState(false);

  const filteredEntries = entries.filter(entry => 
    entry.nama.toLowerCase().includes(search.toLowerCase()) || 
    entry.alamat.toLowerCase().includes(search.toLowerCase())
  );

  const spreadsheetUrl = `https://docs.google.com/spreadsheets/d/${spreadsheetId}/edit`;

  const appsScriptCode = `function doGet(e) {
  const ssId = e.parameter.spreadsheet_id;
  const action = e.parameter.action;

  if (action === 'read') {
    try {
      const sheet = SpreadsheetApp.openById(ssId).getSheets()[0];
      const data = sheet.getDataRange().getValues();
      const result = [];

      // Ambil data mulai baris ke-2 (index 1)
      for (let i = 1; i < data.length; i++) {
        if (data[i][0]) { // Pastikan kolom nama tidak kosong
          result.push({
            nama: data[i][0],
            alamat: data[i][2],
            waktu: data[i][3]
          });
        }
      }

      // Urutkan dari yang terbaru (reverse)
      return ContentService.createTextOutput(JSON.stringify(result.reverse()))
        .setMimeType(ContentService.MimeType.JSON);
    } catch (err) {
      return ContentService.createTextOutput(JSON.stringify({error: err.toString()}))
        .setMimeType(ContentService.MimeType.JSON);
    }
  }
}

function doPost(e) {
  try {
    const data = JSON.parse(e.postData.contents);
    const ss = SpreadsheetApp.openById(data.spreadsheet_id);
    const sheet = ss.getSheets()[0];

    // 1. Handle Upload Gambar ke Drive
    let fileUrl = "No Image";
    if (data.image_base64 && data.folder_id) {
      const folder = DriveApp.getFolderById(data.folder_id);
      const contentType = data.image_base64.substring(5, data.image_base64.indexOf(';'));
      const bytes = Utilities.base64Decode(data.image_base64.split(',')[1]);
      const blob = Utilities.newBlob(bytes, contentType, data.filename + ".jpg");
      const file = folder.createFile(blob);
      fileUrl = file.getUrl();
    }

    // 2. Ambil data Kepala Keluarga
    const head = data.anggota_keluarga.find(m => 
      m.status_hubungan.toUpperCase().includes("KEPALA")
    ) || data.anggota_keluarga[0];

    // 3. Simpan baris baru ke Spreadsheet
    sheet.appendRow([
      head.nama.toUpperCase(),
      "'" + data.nomor_kk, // Pakai petik agar format string tetap terjaga
      data.alamat,
      new Date().toLocaleString('id-ID'),
      fileUrl,
      JSON.stringify(data.anggota_keluarga)
    ]);

    return ContentService.createTextOutput(JSON.stringify({status: "success"}))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({status: "error", message: err.toString()}))
      .setMimeType(ContentService.MimeType.JSON);
  }
}`;

  const copyCode = () => {
    navigator.clipboard.writeText(appsScriptCode);
    alert("Kode berhasil disalin!");
  };

  return (
    <div className="max-w-5xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
        <div>
          <h3 className="text-3xl font-black text-slate-900 tracking-tight">Database Warga</h3>
          <p className="text-slate-500 font-medium">Monitoring data hasil inputan petugas lapangan.</p>
        </div>
        <div className="flex items-center gap-3">
          <button 
            onClick={() => setShowSetup(!showSetup)}
            className={`px-4 py-3 rounded-xl font-bold text-sm transition-all flex items-center gap-2 ${showSetup ? 'bg-indigo-600 text-white' : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-50'}`}
          >
            <i className="fa-solid fa-code"></i> Setup Script
          </button>
          <a 
            href={spreadsheetUrl} 
            target="_blank" 
            rel="noopener noreferrer"
            className="px-4 py-3 bg-green-50 text-green-700 border border-green-200 rounded-xl font-bold text-sm hover:bg-green-100 transition-colors flex items-center gap-2"
          >
            <i className="fa-solid fa-file-excel"></i> Buka Sheet
          </a>
          <button 
            onClick={onBack}
            className="px-6 py-3 bg-slate-900 text-white rounded-xl font-bold flex items-center gap-2 hover:bg-slate-800 transition-colors"
          >
            <i className="fa-solid fa-arrow-left"></i> Kembali
          </button>
        </div>
      </div>

      {showSetup ? (
        <div className="animate-in fade-in zoom-in-95 duration-300">
          <div className="bg-slate-900 rounded-3xl overflow-hidden shadow-2xl">
            <div className="flex items-center justify-between px-6 py-4 bg-slate-800 border-b border-slate-700">
              <div className="flex items-center gap-2 text-slate-400">
                <i className="fa-solid fa-file-code"></i>
                <span className="text-xs font-black uppercase tracking-widest">code.gs</span>
              </div>
              <button 
                onClick={copyCode}
                className="px-4 py-2 bg-indigo-600 text-white text-xs font-bold rounded-lg hover:bg-indigo-700 transition-colors flex items-center gap-2"
              >
                <i className="fa-solid fa-copy"></i> Salin Kode
              </button>
            </div>
            <div className="p-6 overflow-x-auto">
