import React, { useState, useEffect, useCallback } from 'react';
import Header from './components/Header';
import FileUpload from './components/FileUpload';
import KKForm from './components/KKForm';
import SuccessState from './components/SuccessState';
import DatabaseView from './components/DatabaseView';
import { extractKKData } from './services/geminiService';
import { AppState, KKData, SavedEntry } from './types';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(AppState.IDLE);
  const [kkData, setKkData] = useState<KKData | null>(null);
  const [currentImageBase64, setCurrentImageBase64] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [isLoadingHistory, setIsLoadingHistory] = useState(false);
  const [savedHistory, setSavedHistory] = useState<SavedEntry[]>([]);
  const [fetchError, setFetchError] = useState<boolean>(false);

  // Konfigurasi Sistem
  const WEB_APP_URL = "https://script.google.com/macros/s/AKfycbwJINHRQjvu5kncOXVGeplokmmeW5bPyRZ7ojPEQQQEB8FtZFx4x5Dhxm4mV8wygUFb8w/exec";
  const SPREADSHEET_ID = "1mIpV1syBF1GslK1A9l9dYvw4TDO0Yf98sO2wtejQkqs";
  const FOLDER_ID = "1suJP423Z_vZbZV7zlp61_n2uNflqkfGB";

  const fetchHistory = useCallback(async () => {
    setIsLoadingHistory(true);
    setFetchError(false);
    try {
      const response = await fetch(`${WEB_APP_URL}?spreadsheet_id=${SPREADSHEET_ID}&action=read`, {
        method: 'GET',
        cache: 'no-store',
      });

      if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

      const data = await response.json();
      if (Array.isArray(data)) {
        setSavedHistory(data);
        localStorage.setItem('kk_local_history', JSON.stringify(data));
      } else {
        throw new Error("Format data tidak sesuai");
      }
    } catch (err) {
      console.error("Gagal Fetch:", err);
      setFetchError(true);
      const local = localStorage.getItem('kk_local_history');
      if (local) setSavedHistory(JSON.parse(local));
    } finally {
      setIsLoadingHistory(false);
    }
  }, [WEB_APP_URL, SPREADSHEET_ID]);

  useEffect(() => {
    fetchHistory();
  }, [fetchHistory]);

  const handleFileSelect = async (base64: string) => {
    setState(AppState.SCANNING);
    setCurrentImageBase64(base64);
    setError(null);
    try {
      const data = await extractKKData(base64);
      setKkData(data);
      setState(AppState.REVIEWING);
    } catch (err) {
      console.error(err);
      setError("Gagal membaca dokumen. Pastikan gambar tajam dan tidak silau.");
      setState(AppState.IDLE);
    }
  };

  const handleSave = async (finalData: KKData) => {
    setIsSaving(true);
    try {
      const kepalaKeluarga = finalData.anggota_keluarga.find(
        m => m.status_hubungan.toUpperCase().includes("KEPALA")
      ) || finalData.anggota_keluarga[0];

      const rawName = kepalaKeluarga?.nama || "TANPA_NAMA";
      const safeName = rawName.trim().toUpperCase().replace(/[^A-Z0-9\s]/g, '').replace(/\s+/g, '_');
      const fileName = `KK_${safeName}`;

      const payload = {
        spreadsheet_id: SPREADSHEET_ID,
        folder_id: FOLDER_ID,
        image_base64: currentImageBase64,
        filename: fileName,
        ...finalData
      };

      await fetch(WEB_APP_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });

      const newEntry: SavedEntry = {
        nama: rawName.toUpperCase(),
        alamat: finalData.alamat || "Alamat tidak terbaca",
        waktu: new Date().toLocaleTimeString('id-ID')
      };

      const updatedHistory = [newEntry, ...savedHistory];
      setSavedHistory(updatedHistory);
      localStorage.setItem('kk_local_history', JSON.stringify(updatedHistory));

      setTimeout(() => {
        setIsSaving(false);
        setState(AppState.SAVED);
        fetchHistory(); 
      }, 1500);

    } catch (err) {
      console.error(err);
      setError("Data gagal dikirim ke server. Cek koneksi Anda.");
      setIsSaving(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans">
      <Header />

      <main className="flex-grow container mx-auto px-4 py-8">
        {state === AppState.IDLE && (
          <div className="max-w-4xl mx-auto space-y-12 animate-in fade-in duration-700">
            <div className="text-center">
              <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-indigo-50 text-indigo-600 text-[10px] font-black uppercase tracking-widest mb-6">
                <i className="fa-solid fa-clock-rotate-left"></i>
                Log Aktivitas Aktif
              </div>
              <h2 className="text-4xl font-black text-slate-900 leading-tight">Digitalisasi Kartu Keluarga</h2>
              <p className="mt-4 text-slate-500 text-lg max-w-xl mx-auto">
                Scan Kartu Keluarga untuk input data otomatis ke sistem riwayat pusat.
              </p>
            </div>

            {error && (
              <div className="p-4 bg-red-50 border border-red-100 rounded-2xl flex items-start gap-3 text-red-700 max-w-2xl mx-auto animate-in slide-in-from-top-4">
                <i className="fa-solid fa-circle-exclamation mt-1"></i>
                <p className="text-sm font-bold">{error}</p>
              </div>
            )}

            <FileUpload onFileSelect={handleFileSelect} isLoading={false} />

            <div className="text-center">
              <button 
                onClick={() => setState(AppState.DATABASE)}
                className="px-8 py-4 bg-white text-indigo-600 border border-indigo-100 rounded-2xl font-bold shadow-sm hover:shadow-md hover:bg-indigo-50 transition-all flex items-center justify-center gap-3 mx-auto"
              >
                <i className={`fa-solid ${isLoadingHistory ? 'fa-spinner animate-spin' : 'fa-history'} text-xl`}></i>
                {isLoadingHistory ? 'Memuat Riwayat...' : 'Lihat Riwayat Penginputan'}
              </button>
              {fetchError && (
                <div className="mt-4 flex flex-col items-center gap-1">
                  <p className="text-[10px] text-red-500 font-bold uppercase tracking-widest">
                    Gagal Sinkronisasi Riwayat
                  </p>
                  <button onClick={fetchHistory} className="text-[9px] text-indigo-600 font-black underline uppercase">Refresh Ulang</button>
                </div>
              )}
            </div>
          </div>
        )}

        {state === AppState.SCANNING && (
          <div className="flex flex-col items-center justify-center py-24">
            <div className="relative w-32 h-32 mb-8">
              <div className="absolute inset-0 border-4 border-indigo-100 rounded-[2.5rem]"></div>
              <div className="absolute inset-0 border-4 border-indigo-600 rounded-[2.5rem] border-t-transparent animate-spin"></div>
              <div className="absolute inset-6 bg-indigo-50 rounded-2xl flex items-center justify-center text-indigo-600 text-4xl">
                <i className="fa-solid fa-bolt-lightning animate-pulse"></i>
              </div>
            </div>
            <h3 className="text-3xl font-black text-slate-900 tracking-tight">Memproses Dokumen...</h3>
            <p className="text-slate-500 mt-3 text-lg font-medium">Data sedang dianalisis oleh AI.</p>
          </div>
        )}

        {state === AppState.REVIEWING && kkData && (
          <div className="max-w-6xl mx-auto animate-in fade-in slide-in-from-bottom-8 duration-500">
            <div className="flex flex-col md:flex-row md:items-end justify-between mb-8 gap-4">
              <div>
                <span className="text-indigo-600 font-bold text-xs uppercase tracking-widest bg-indigo-50 px-3 py-1 rounded-full mb-3 inline-block">Validasi Data</span>
                <h3 className="text-3xl font-black text-slate-900">Review Sebelum Simpan</h3>
                <p className="text-slate-500 mt-1 text-sm font-medium">Cek riwayat di bawah untuk menghindari data ganda.</p>
              </div>
              <button onClick={() => setState(AppState.IDLE)} className="px-6 py-3 text-sm font-bold text-slate-500 bg-slate-100 rounded-2xl hover:bg-slate-200 transition-all flex items-center gap-2">
                <i className="fa-solid fa-arrow-left"></i> Kembali
              </button>
            </div>
            <KKForm 
              data={kkData} 
              onSave={handleSave} 
              onCancel={() => setState(AppState.IDLE)} 
              isSaving={isSaving}
              existingEntries={savedHistory}
            />
          </div>
        )}

        {state === AppState.SAVED && (
          <SuccessState 
            onReset={() => setState(AppState.IDLE)} 
            onViewDatabase={() => setState(AppState.DATABASE)} 
          />
        )}

        {state === AppState.DATABASE && (
          <DatabaseView 
            entries={savedHistory} 
            isLoading={isLoadingHistory}
            hasError={fetchError}
            spreadsheetId={SPREADSHEET_ID}
            onRefresh={fetchHistory}
            onBack={() => setState(AppState.IDLE)} 
          />
        )}
      </main>

      <footer className="py-10 bg-white border-t border-slate-200 mt-auto">
        <div className="container mx-auto px-4 text-center">
          <p className="text-slate-400 text-[10px] uppercase font-black tracking-[0.3em]">KK-OCR PRO • LOG RIWAYAT TERPUSAT</p>
        </div>
      </footer>
    </div>
  );
};

