          <div className="mt-8 p-6 bg-indigo-600 rounded-3xl text-white flex flex-col sm:flex-row items-center justify-between gap-6 shadow-xl shadow-indigo-100">
            <div className="flex items-center gap-5">
              <div className="w-14 h-14 bg-white/20 rounded-2xl flex items-center justify-center text-2xl">
                <i className="fa-solid fa-list-check"></i>
              </div>
              <div>
                <p className="text-xl font-black">{entries.length} Riwayat Input</p>
                <p className="text-indigo-100 text-sm font-medium">Log aktivitas petugas tersimpan permanen.</p>
              </div>
            </div>
            <button onClick={onRefresh} className="px-6 py-3 bg-white text-indigo-600 rounded-xl font-black text-sm flex items-center gap-2 hover:scale-105 transition-transform active:scale-95">
              <i className="fa-solid fa-rotate"></i>
              Refresh Riwayat
            </button>
          </div>
        </>
      )}
    </div>
  );
};

