        kewarganegaraan: 'WNI',
        nama_ayah: '',
        nama_ibu: ''
      }]
    };
    setKkData(emptyData);
    setCurrentImageBase64(null);
    setState(AppState.REVIEWING);
  };

  const handleSave = async (finalData: KKData) => {
    setIsSaving(true);
    try {
      const kepalaKeluarga = finalData.anggota_keluarga.find(
        m => m.status_hubungan.toUpperCase().includes("KEPALA")
      ) || finalData.anggota_keluarga[0];

      const payload = {
        spreadsheet_id: SPREADSHEET_ID,
        folder_id: FOLDER_ID,
        image_base64: currentImageBase64,
        filename: `KK_${kepalaKeluarga?.nama.replace(/\s+/g, '_')}`,
        ...finalData
      };

      await fetch(WEB_APP_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });

      // Optimistic update
      const newEntry: SavedEntry = {
        nama: kepalaKeluarga?.nama.toUpperCase() || "TANPA NAMA",
        alamat: finalData.alamat || "-",
        waktu: new Date().toLocaleTimeString('id-ID')
      };

      setSavedHistory(prev => [newEntry, ...prev]);
      setState(AppState.SAVED);

      setTimeout(fetchHistory, 3000);
    } catch (err) {
      setError("Gagal menyimpan ke server.");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col font-sans pb-32">
      <Header />

      <main className="flex-grow container mx-auto px-4 py-6">
        {activeTab === 'scanner' ? (
          <div className="max-w-4xl mx-auto">
            {state === AppState.IDLE && (
              <div className="space-y-8 animate-in fade-in duration-500">
                <div className="text-center py-6">
                  <h2 className="text-3xl font-black text-slate-900 tracking-tighter uppercase italic">
                    SCANNER <span className="text-indigo-600">KK PRO</span>
                  </h2>
                  <p className="text-[10px] text-slate-400 mt-2 font-black uppercase tracking-[0.3em]">Digitalisasi Data Warga</p>
                </div>

                <FileUpload onFileSelect={handleFileSelect} isLoading={false} />

                <button 
                  onClick={startManualInput}
                  className="w-full max-w-md mx-auto flex items-center justify-center gap-3 px-6 py-4 bg-white border-2 border-dashed border-slate-200 text-slate-500 rounded-2xl hover:border-indigo-400 hover:text-indigo-600 transition-all"
                >
                  <i className="fa-solid fa-keyboard text-lg"></i>
                  <span className="font-bold text-sm uppercase tracking-widest">Input Manual (Tanpa Scan)</span>
                </button>
              </div>
            )}

            {state === AppState.SCANNING && (
              <div className="flex flex-col items-center justify-center py-20 animate-pulse">
                <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-6"></div>
                <h3 className="text-xl font-black text-slate-900 tracking-widest uppercase">Menganalisis Dokumen...</h3>
              </div>
            )}

            {state === AppState.REVIEWING && kkData && (
              <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                <div className="flex items-center justify-between mb-6">
                  <h3 className="text-xl font-black text-slate-900 uppercase italic">Validasi Data</h3>
                  <button onClick={() => setState(AppState.IDLE)} className="text-xs font-black text-slate-400 uppercase tracking-widest hover:text-red-500">
                    <i className="fa-solid fa-xmark mr-1"></i> Batal
                  </button>
                </div>
                <KKForm 
                  data={kkData} 
                  onSave={handleSave} 
                  onCancel={() => setState(AppState.IDLE)} 
                  isSaving={isSaving}
                  existingEntries={savedHistory}
                />
              </div>
            )}

            {state === AppState.SAVED && (
              <SuccessState 
                onReset={() => setState(AppState.IDLE)} 
                onViewDatabase={() => setActiveTab('history')} 
              />
            )}
          </div>
        ) : (
          <DatabaseView 
            entries={savedHistory} 
            isLoading={isLoadingHistory}
            hasError={fetchError}
            spreadsheetId={SPREADSHEET_ID}
            onRefresh={fetchHistory}
            onBack={() => setActiveTab('scanner')} 
          />
        )}
      </main>

      {/* BOTTOM NAVIGATION */}
      <nav className="fixed bottom-6 left-1/2 -translate-x-1/2 bg-slate-900/95 backdrop-blur-xl p-2 rounded-[2rem] shadow-2xl flex gap-2 z-50 border border-white/10 animate-in slide-in-from-bottom-10 duration-500">
        <button 
          onClick={() => { setActiveTab('scanner'); if(state === AppState.SAVED) setState(AppState.IDLE); }}
