import React, { useState } from 'react';
import { SavedEntry } from '../types';

interface DatabaseViewProps {
  entries: SavedEntry[];
  isLoading?: boolean;
  hasError?: boolean;
  spreadsheetId: string;
  onRefresh: () => void;
  onBack: () => void;
}

const DatabaseView: React.FC<DatabaseViewProps> = ({ entries, isLoading, hasError, spreadsheetId, onRefresh, onBack }) => {
  const [search, setSearch] = useState("");
  const [showSetup, setShowSetup] = useState(false);

  const filteredEntries = entries.filter(entry => 
    (entry.nama || "").toLowerCase().includes(search.toLowerCase()) || 
    (entry.alamat || "").toLowerCase().includes(search.toLowerCase()) ||
    (entry.status || "").toLowerCase().includes(search.toLowerCase())
  );

  const spreadsheetUrl = `https://docs.google.com/spreadsheets/d/${spreadsheetId}/edit`;

  const appsScriptCode = `function doGet(e) {
  const ssId = e.parameter.spreadsheet_id;
  const action = e.parameter.action;

  if (action === 'read') {
    try {
      const ss = SpreadsheetApp.openById(ssId);
      const sheet = ss.getSheets()[0]; 
      const data = sheet.getDataRange().getValues();
      const result = [];

      // Indeks Kolom (0-based):
      // Kolom I = Index 8 (Nama)
      // Kolom C = Index 2 (Alamat)
      // Kolom R = Index 17 (Status Hubungan)
      // Kolom D = Index 3 (Waktu - opsional)

      for (let i = 1; i < data.length; i++) {
        const row = data[i];
        // Validasi jika baris memiliki data (cek kolom I / Nama)
        if (row[8] && row[8].toString().trim() !== "") { 
          result.push({
            nama: row[8].toString(),
            alamat: row[2] ? row[2].toString() : "-",
            status: row[17] ? row[17].toString() : "-",
            waktu: row[3] ? row[3].toString() : "-"
          });
        }
      }

      return ContentService.createTextOutput(JSON.stringify({
        status: 'success',
        data: result.reverse(),
        info: "Membaca Kolom I, C, R. Total: " + result.length + " data"
      })).setMimeType(ContentService.MimeType.JSON);

    } catch (err) {
      return ContentService.createTextOutput(JSON.stringify({
        status: 'error',
        message: "Script Error: " + err.toString()
      })).setMimeType(ContentService.MimeType.JSON);
    }
  }
}

function doPost(e) {
  try {
    const data = JSON.parse(e.postData.contents);
    const ss = SpreadsheetApp.openById(data.spreadsheet_id);
    const sheet = ss.getSheets()[0];

    let fileUrl = "No Image";
    if (data.image_base64 && data.folder_id) {
      try {
        const folder = DriveApp.getFolderById(data.folder_id);
        const contentType = data.image_base64.substring(5, data.image_base64.indexOf(';'));
        const bytes = Utilities.base64Decode(data.image_base64.split(',')[1]);
        const blob = Utilities.newBlob(bytes, contentType, data.filename + ".jpg");
        const file = folder.createFile(blob);
        fileUrl = file.getUrl();
      } catch(fErr) {
        fileUrl = "Error Upload: " + fErr.toString();
      }
    }

    const head = data.anggota_keluarga.find(m => 
      m.status_hubungan.toUpperCase().includes("KEPALA")
    ) || data.anggota_keluarga[0];

    // PERHATIKAN: appendRow ini mungkin perlu Anda sesuaikan jika kolom I dan R berada di luar 6 kolom pertama
    // Skrip default ini hanya mengisi Kolom A-F. Jika Anda sudah punya data di Kolom I & R, 
    // pastikan data tersebut diisi secara manual atau sesuaikan array di bawah ini.
    sheet.appendRow([
      head.nama.toUpperCase(), // A
      "'" + data.nomor_kk,     // B
      data.alamat,             // C
      new Date().toLocaleString('id-ID'), // D
      fileUrl,                 // E
      JSON.stringify(data.anggota_keluarga) // F
    ]);

    return ContentService.createTextOutput(JSON.stringify({status: "success"}))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({status: "error", message: err.toString()}))
      .setMimeType(ContentService.MimeType.JSON);
  }
}`;

  const copyCode = () => {
    navigator.clipboard.writeText(appsScriptCode);
    alert("Kode Script Versi 3 berhasil disalin!");
  };

  return (
    <div className="max-w-4xl mx-auto animate-in fade-in duration-500">
      <div className="flex justify-between items-center mb-8">
        <div>
          <h2 className="text-2xl font-black text-slate-900 uppercase italic">Riwayat Input</h2>
          <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Sinkronisasi Kolom I, C, R</p>
        </div>
        <div className="flex gap-2">
           <button 
            onClick={() => setShowSetup(!showSetup)}
            className={`w-10 h-10 border rounded-xl flex items-center justify-center transition-colors shadow-sm ${showSetup ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white border-slate-200 text-slate-400 hover:text-indigo-600'}`}
            title="Setup Script"
          >
            <i className="fa-solid fa-code"></i>
          </button>
          <button onClick={onRefresh} className="w-10 h-10 bg-white border border-slate-200 rounded-xl flex items-center justify-center text-slate-400 hover:text-indigo-600 transition-colors shadow-sm">
            <i className={`fa-solid fa-arrows-rotate ${isLoading ? 'animate-spin' : ''}`}></i>
          </button>
        </div>
      </div>

      {showSetup && (
        <div className="mb-8 p-6 bg-slate-900 rounded-3xl animate-in zoom-in-95">
          <div className="flex items-center justify-between mb-4">
             <span className="text-xs font-black text-indigo-400 uppercase tracking-widest">Update code.gs (Script Versi 3 - Custom Columns)</span>
             <button onClick={copyCode} className="px-4 py-2 bg-indigo-600 text-white text-[10px] font-black rounded-lg uppercase">Salin Script</button>
          </div>
          <pre className="text-[10px] text-indigo-200 font-mono overflow-x-auto p-4 bg-slate-800 rounded-xl max-h-60">
            {appsScriptCode}
          </pre>
          <div className="mt-4 p-3 bg-indigo-500/10 border border-indigo-500/20 rounded-xl">
            <p className="text-[10px] text-indigo-300 font-bold uppercase mb-1">Peta Kolom Aktif:</p>
            <div className="grid grid-cols-3 gap-2 text-[9px] font-mono text-slate-400">
              <div className="bg-slate-800 p-2 rounded">Kolom I (8) &rarr; Nama</div>
              <div className="bg-slate-800 p-2 rounded">Kolom C (2) &rarr; Alamat</div>
              <div className="bg-slate-800 p-2 rounded">Kolom R (17) &rarr; Status</div>
            </div>
          </div>
        </div>
      )}

      <div className="mb-6 relative">
        <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-slate-400">
          <i className="fa-solid fa-magnifying-glass"></i>
        </div>
        <input
          type="text"
          placeholder="Cari nama, alamat, atau status..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="w-full pl-12 pr-4 py-4 bg-white border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none shadow-sm font-bold text-sm"
        />
      </div>

      {isLoading && entries.length === 0 ? (
        <div className="flex flex-col items-center py-20 text-slate-300">
          <div className="w-10 h-10 border-4 border-slate-100 border-t-indigo-600 rounded-full animate-spin mb-4"></div>
          <p className="text-xs font-black uppercase tracking-widest">Sinkronisasi Cloud...</p>
        </div>
      ) : filteredEntries.length === 0 ? (
        <div className="text-center py-20 bg-white rounded-[2.5rem] border-2 border-dashed border-slate-100">
          <i className="fa-solid fa-database text-4xl text-slate-200 mb-4"></i>
          <p className="text-slate-400 font-bold uppercase text-[10px] tracking-widest">
             {hasError ? 'Koneksi Bermasalah' : 'Data tidak ditemukan'}
          </p>
        </div>
      ) : (
        <div className="flex flex-col gap-4">
          {filteredEntries.map((entry, idx) => (
            <div key={idx} className="bg-white p-5 rounded-[2rem] shadow-sm border border-slate-100 flex flex-col md:flex-row md:items-center justify-between gap-4 group hover:border-indigo-200 transition-all">
              <div className="flex gap-4 items-center flex-1">
                <div className="w-14 h-14 bg-slate-50 text-slate-400 rounded-2xl flex items-center justify-center font-black text-xl group-hover:bg-indigo-50 group-hover:text-indigo-600 transition-colors shrink-0">
                  {(entry.nama || "U").charAt(0)}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 flex-wrap">
                    <h4 className="font-black text-slate-900 leading-tight group-hover:text-indigo-600 transition-colors uppercase truncate max-w-[200px]">{entry.nama}</h4>
                    <span className="text-[8px] font-black bg-slate-100 text-slate-500 px-2 py-0.5 rounded-md uppercase tracking-tighter">
                      {entry.status}
