                </div>
              </div>
              <div className="flex items-center justify-between md:justify-end gap-3 border-t md:border-t-0 pt-3 md:pt-0 border-slate-50">
                <span className="text-[9px] font-black bg-indigo-50 text-indigo-600 px-4 py-2 rounded-full uppercase tracking-widest border border-indigo-100">
                  <i className="fa-solid fa-check-circle mr-1"></i> Terbaca
