import { GoogleGenAI, Type } from "@google/genai";
import { KKData } from "../types";

// Fix: Always use the exact initialization syntax from guidelines
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const kkSchema = {
  type: Type.OBJECT,
  properties: {
    nomor_kk: { type: Type.STRING, description: "Nomor Kartu Keluarga" },
    alamat: { type: Type.STRING, description: "Alamat Lengkap" },
    rt_rw: { type: Type.STRING, description: "RT/RW" },
    kode_pos: { type: Type.STRING, description: "Kode Pos" },
    desa_kelurahan: { type: Type.STRING, description: "Desa atau Kelurahan" },
    kecamatan: { type: Type.STRING, description: "Kecamatan" },
    kabupaten_kota: { type: Type.STRING, description: "Kabupaten atau Kota" },
    provinsi: { type: Type.STRING, description: "Provinsi" },
    anggota_keluarga: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          nama: { type: Type.STRING },
          nik: { type: Type.STRING },
          jenis_kelamin: { type: Type.STRING },
          tempat_lahir: { type: Type.STRING },
          tanggal_lahir: { type: Type.STRING },
          agama: { type: Type.STRING },
          pendidikan: { type: Type.STRING },
          jenis_pekerjaan: { type: Type.STRING },
          status_perkawinan: { type: Type.STRING },
          status_hubungan: { type: Type.STRING },
          kewarganegaraan: { type: Type.STRING },
          nama_ayah: { type: Type.STRING },
          nama_ibu: { type: Type.STRING },
        },
      },
    },
  },
  required: ["nomor_kk", "anggota_keluarga"],
};

export const extractKKData = async (base64Image: string): Promise<KKData> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: [
        {
          parts: [
            {
              inlineData: {
                mimeType: "image/jpeg",
                data: base64Image.split(",")[1],
              },
            },
            {
              text: "Ekstrak data lengkap dari dokumen Kartu Keluarga ini ke dalam format JSON yang terstruktur sesuai skema. Pastikan NIK dan Nomor KK terbaca dengan benar. Jika data tidak ditemukan, biarkan string kosong.",
            },
          ],
        },
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: kkSchema,
      },
    });

    // Fix: Access .text property as per guidelines
    const text = response.text;
    if (!text) throw new Error("Gagal mengekstrak teks dari gambar.");

    return JSON.parse(text) as KKData;
  } catch (error) {
    console.error("Error in extractKKData:", error);
    throw error;
  }
};

import React, { useState, useMemo } from 'react';
import { KKData, KKMember, SavedEntry } from '../types';

interface KKFormProps {
  data: KKData;
  onSave: (finalData: KKData) => void;
  onCancel: () => void;
  isSaving?: boolean;
  existingEntries?: SavedEntry[];
}

const KKForm: React.FC<KKFormProps> = ({ data, onSave, onCancel, isSaving, existingEntries = [] }) => {
  const [formData, setFormData] = useState<KKData>(data);

  // Deteksi duplikasi berdasarkan nama Kepala Keluarga
  const headOfHousehold = useMemo(() => {
    return formData.anggota_keluarga.find(
      m => m.status_hubungan.toUpperCase().includes("KEPALA")
    ) || formData.anggota_keluarga[0];
  }, [formData.anggota_keluarga]);

  const isDuplicate = useMemo(() => {
    if (!headOfHousehold || !headOfHousehold.nama) return false;
    const name = headOfHousehold.nama.toUpperCase().trim();
    return existingEntries.some(entry => entry.nama.toUpperCase().trim() === name);
  }, [headOfHousehold, existingEntries]);

  const handleHeaderChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
