import React, { useState } from 'react';
import { SavedEntry } from '../types';

interface DatabaseViewProps {
  entries: SavedEntry[];
  isLoading?: boolean;
  hasError?: boolean;
  spreadsheetId: string;
  onRefresh: () => void;
  onBack: () => void;
}

const DatabaseView: React.FC<DatabaseViewProps> = ({ entries, isLoading, hasError, spreadsheetId, onRefresh, onBack }) => {
  const [search, setSearch] = useState("");
  const [showSetup, setShowSetup] = useState(false);

  const filteredEntries = entries.filter(entry => 
    (entry.nama || "").toLowerCase().includes(search.toLowerCase()) || 
    (entry.nomor_kk || "").toLowerCase().includes(search.toLowerCase()) ||
    (entry.alamat || "").toLowerCase().includes(search.toLowerCase())
  );

  const appsScriptCode = `function doGet(e) {
  const ssId = e.parameter.spreadsheet_id;
  const action = e.parameter.action;

  if (action === 'read') {
    try {
      const ss = SpreadsheetApp.openById(ssId);
      const sheet = ss.getSheets()[0]; 
      const data = sheet.getDataRange().getValues();
      const result = [];

      for (let i = 1; i < data.length; i++) {
        const row = data[i];
        if (row[1] && row[1].toString().trim() !== "") { 
          result.push({
            nama: row[0] ? row[0].toString() : "-",
            nomor_kk: row[1] ? row[1].toString() : "-",
            alamat: row[2] ? row[2].toString() : "-",
            waktu: row[3] ? row[3].toString() : "-",
            nik: row[9] ? row[9].toString() : "-",
            jumlah_anggota: row[10] ? row[10] : 0,
            status: row[17] ? row[17].toString() : "-"
          });
        }
      }

      return ContentService.createTextOutput(JSON.stringify({
        status: 'success',
        data: result.reverse()
      })).setMimeType(ContentService.MimeType.JSON);
    } catch (err) {
      return ContentService.createTextOutput(JSON.stringify({status: 'error', message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
    }
  }
}

function doPost(e) {
  try {
    const data = JSON.parse(e.postData.contents);
    const ss = SpreadsheetApp.openById(data.spreadsheet_id);
    const sheet = ss.getSheets()[0];

    let fileUrl = "No Image";
    if (data.image_base64 && data.folder_id) {
      const folder = DriveApp.getFolderById(data.folder_id);
      const bytes = Utilities.base64Decode(data.image_base64.split(',')[1]);
      const file = folder.createFile(Utilities.newBlob(bytes, 'image/jpeg', data.filename + ".jpg"));
      fileUrl = file.getUrl();
    }

    const head = data.anggota_keluarga.find(m => m.status_hubungan.toUpperCase().includes("KEPALA")) || data.anggota_keluarga[0];
    const lastRow = sheet.getLastRow() + 1;

    sheet.getRange(lastRow, 1).setValue(head.nama.toUpperCase()); // A: Nama Kepala
    sheet.getRange(lastRow, 2).setValue("'" + data.nomor_kk);      // B: No KK (Validasi Utama)
    sheet.getRange(lastRow, 3).setValue(data.alamat);             // C: Alamat
    sheet.getRange(lastRow, 4).setValue(new Date().toLocaleString('id-ID')); // D: Waktu
    sheet.getRange(lastRow, 5).setValue(fileUrl);                 // E: Foto
    sheet.getRange(lastRow, 9).setValue(head.nama.toUpperCase()); // I: Nama Lagi
    sheet.getRange(lastRow, 10).setValue("'" + head.nik);         // J: NIK
    sheet.getRange(lastRow, 11).setValue(data.jumlah_anggota);    // K: Jumlah Anggota
    sheet.getRange(lastRow, 18).setValue(head.status_hubungan);   // R: Status

    return ContentService.createTextOutput(JSON.stringify({status: "success"})).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({status: "error", message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
  }
}`;

  const copyCode = () => {
    navigator.clipboard.writeText(appsScriptCode);
    alert("Script Versi 5 (Validasi No KK & Jumlah Anggota) disalin!");
  };

  return (
    <div className="max-w-4xl mx-auto animate-in fade-in duration-500">
      <div className="flex justify-between items-end mb-8">
        <div>
          <h2 className="text-2xl font-black text-slate-900 uppercase italic leading-none tracking-tighter">Database Riwayat</h2>
          <p className="text-[10px] text-indigo-500 font-black uppercase tracking-[0.2em] mt-2">Pengecekan No. KK Aktif</p>
        </div>
        <div className="flex gap-2">
           <button onClick={() => setShowSetup(!showSetup)} className={`w-11 h-11 border rounded-2xl flex items-center justify-center transition-all ${showSetup ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 text-slate-400 hover:text-indigo-600 shadow-sm'}`}>
            <i className="fa-solid fa-code"></i>
          </button>
          <button onClick={onRefresh} className="w-11 h-11 bg-white border border-slate-200 rounded-2xl flex items-center justify-center text-slate-400 hover:text-indigo-600 transition-all shadow-sm">
            <i className={`fa-solid fa-arrows-rotate ${isLoading ? 'animate-spin' : ''}`}></i>
          </button>
        </div>
      </div>

      {showSetup && (
        <div className="mb-8 p-6 bg-slate-900 rounded-[2rem] shadow-2xl animate-in zoom-in-95">
          <div className="flex items-center justify-between mb-4">
             <span className="text-xs font-black text-indigo-400 uppercase tracking-widest">Update Script Google (V5)</span>
             <button onClick={copyCode} className="px-4 py-2 bg-indigo-600 text-white text-[10px] font-black rounded-xl uppercase hover:bg-indigo-700">Update Script</button>
          </div>
          <pre className="text-[10px] text-indigo-200 font-mono overflow-x-auto p-4 bg-slate-800 rounded-2xl max-h-60 mb-4">{appsScriptCode}</pre>
          <div className="grid grid-cols-2 gap-3">
             <div className="bg-slate-800/50 p-3 rounded-xl border border-white/5"><p className="text-[9px] text-slate-400 font-black uppercase">Validasi</p><p className="text-xs text-white font-bold">Kolom B (No. KK)</p></div>
             <div className="bg-slate-800/50 p-3 rounded-xl border border-white/5"><p className="text-[9px] text-slate-400 font-black uppercase">Jumlah</p><p className="text-xs text-white font-bold">Kolom K (Counter)</p></div>
          </div>
        </div>
      )}

      <div className="mb-8 relative">
        <input type="text" placeholder="Cari Nomor KK, Kepala Keluarga, atau Alamat..." value={search} onChange={(e) => setSearch(e.target.value)} className="w-full pl-14 pr-6 py-5 bg-white border border-slate-100 rounded-3xl focus:ring-4 focus:ring-indigo-50 outline-none shadow-sm font-bold text-sm transition-all" />
        <div className="absolute inset-y-0 left-0 pl-6 flex items-center pointer-events-none text-slate-300"><i className="fa-solid fa-magnifying-glass text-lg"></i></div>
      </div>

      <div className="space-y-4">
        {filteredEntries.length > 0 ? filteredEntries.map((entry, idx) => (
          <div key={idx} className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-50 flex flex-col md:flex-row md:items-center justify-between gap-6 group hover:border-indigo-100 transition-all hover:shadow-xl hover:shadow-indigo-100/10">
            <div className="flex gap-5 items-center flex-1">
              <div className="w-16 h-16 bg-slate-50 text-indigo-600 rounded-2xl flex flex-col items-center justify-center font-black shrink-0 border border-slate-100">
                <span className="text-xl leading-none">{entry.jumlah_anggota || 0}</span>
                <span className="text-[7px] uppercase mt-1 tracking-tighter">Anggota</span>
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 mb-1">
                  <h4 className="font-black text-slate-900 uppercase truncate text-base">{entry.nama}</h4>
                  <span className="text-[8px] font-black bg-emerald-50 text-emerald-600 px-2 py-0.5 rounded-md uppercase">Terverifikasi</span>
                </div>
                <div className="flex flex-col gap-1 sm:flex-row sm:items-center sm:gap-4">
                  <p className="text-[10px] text-indigo-600 font-mono font-bold tracking-tight bg-indigo-50 px-2 py-0.5 rounded">NO KK: {entry.nomor_kk}</p>
                  <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest line-clamp-1 flex-1">{entry.alamat}</p>
                </div>
              </div>
            </div>
            <div className="flex flex-col items-end shrink-0">
              <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">{entry.waktu}</div>
              <div className="flex gap-1">
                <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
                <div className="w-2 h-2 rounded-full bg-indigo-300"></div>
                <div className="w-2 h-2 rounded-full bg-slate-200"></div>
              </div>
            </div>
          </div>
        )) : (
          <div className="py-20 text-center bg-white rounded-[2.5rem] border border-dashed border-slate-200">
            <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-4 text-slate-300">
              <i className="fa-solid fa-database text-3xl"></i>
            </div>
            <p className="text-slate-400 font-black uppercase text-xs tracking-widest">Database Kosong atau Tidak Ditemukan</p>
          </div>
        )}
      </div>
    </div>
  );
};

