import React, { useState, useMemo } from 'react';
import { KKData, KKMember, SavedEntry } from '../types';

interface KKFormProps {
  data: KKData;
  onSave: (finalData: KKData) => void;
  onCancel: () => void;
  isSaving?: boolean;
  existingEntries?: SavedEntry[];
}

const KKForm: React.FC<KKFormProps> = ({ data, onSave, onCancel, isSaving, existingEntries = [] }) => {
  const [formData, setFormData] = useState<KKData>(data);

  // Validasi Duplikasi Berdasarkan Nomor KK
  const isDuplicate = useMemo(() => {
    if (!formData.nomor_kk) return false;
    const currentNoKK = formData.nomor_kk.trim();
    return existingEntries.some(entry => entry.nomor_kk && entry.nomor_kk.trim() === currentNoKK);
  }, [formData.nomor_kk, existingEntries]);

  const handleHeaderChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleMemberChange = (index: number, e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    const newMembers = [...formData.anggota_keluarga];
    newMembers[index] = { ...newMembers[index], [name]: value };
    setFormData(prev => ({ ...prev, anggota_keluarga: newMembers }));
  };

  const addMember = () => {
    const newMember: KKMember = {
      nama: '', nik: '', jenis_kelamin: 'LAKI-LAKI', tempat_lahir: '', tanggal_lahir: '',
      agama: 'ISLAM', pendidikan: '', jenis_pekerjaan: '', status_perkawinan: 'BELUM KAWIN',
      status_hubungan: 'ANGGOTA KELUARGA', kewarganegaraan: 'WNI', nama_ayah: '', nama_ibu: ''
    };
    setFormData(prev => ({
      ...prev,
      anggota_keluarga: [...prev.anggota_keluarga, newMember]
    }));
  };

  const removeMember = (index: number) => {
    const newMembers = formData.anggota_keluarga.filter((_, i) => i !== index);
    setFormData(prev => ({ ...prev, anggota_keluarga: newMembers }));
  };

  const inputClass = "w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm transition-all font-medium text-slate-700";
  const labelClass = "text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1.5 block";

  return (
    <div className="max-w-4xl mx-auto space-y-8 pb-40 animate-in fade-in slide-in-from-bottom-4 duration-500">
      {/* Alert Duplikasi Nomor KK */}
      {isDuplicate && (
        <div className="bg-rose-50 border-2 border-rose-100 p-6 rounded-3xl flex items-center gap-5 shadow-sm">
          <div className="w-12 h-12 bg-rose-500 text-white rounded-2xl flex items-center justify-center shrink-0">
            <i className="fa-solid fa-triangle-exclamation text-xl"></i>
          </div>
          <div>
            <h5 className="font-black text-rose-900 text-sm uppercase tracking-tight">Nomor KK Terdeteksi Ganda!</h5>
            <p className="text-[11px] text-rose-600 font-bold uppercase mt-1 leading-relaxed">
              KK No. <span className="underline font-mono">{formData.nomor_kk}</span> sudah ada di riwayat database.
            </p>
          </div>
        </div>
      )}

      {/* Bagian Header KK */}
      <section className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 p-8">
        <div className="flex items-center gap-3 mb-8 border-b border-slate-50 pb-6">
          <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-xl">
            <i className="fa-solid fa-file-invoice"></i>
          </div>
          <div>
            <h4 className="font-black text-slate-900 uppercase italic tracking-tighter text-lg leading-tight">Data Header KK</h4>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Informasi Utama Dokumen</p>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <div className="lg:col-span-2">
            <label className={labelClass}>Nomor Kartu Keluarga</label>
            <input name="nomor_kk" value={formData.nomor_kk} onChange={handleHeaderChange} className={`${inputClass} font-mono font-bold text-indigo-600 text-base`} />
