import React, { useState, useMemo } from 'react';
import { SavedEntry } from '../types';

interface DatabaseViewProps {
  entries: SavedEntry[];
  isLoading?: boolean;
  hasError?: boolean;
  spreadsheetId: string;
  onRefresh: () => void;
  onBack: () => void;
}

const DatabaseView: React.FC<DatabaseViewProps> = ({ entries, isLoading, hasError, spreadsheetId, onRefresh, onBack }) => {
  const [search, setSearch] = useState("");
  const [showSetup, setShowSetup] = useState(false);

  // Statistik Data
  const stats = useMemo(() => {
    const uniqueKK = new Set(entries.map(e => e.nomor_kk)).size;
    const totalJiwa = entries.reduce((acc, curr) => acc + (curr.jumlah_anggota || 1), 0);
    return { uniqueKK, totalJiwa, totalEntries: entries.length };
  }, [entries]);

  const filteredEntries = entries.filter(entry => 
    (entry.nama || "").toLowerCase().includes(search.toLowerCase()) || 
    (entry.nomor_kk || "").toLowerCase().includes(search.toLowerCase()) ||
    (entry.alamat || "").toLowerCase().includes(search.toLowerCase())
  );

  const appsScriptCode = `function doGet(e) {
  const ssId = e.parameter.spreadsheet_id;
  const action = e.parameter.action;

  if (action === 'read') {
    try {
      const ss = SpreadsheetApp.openById(ssId);
      const sheet = ss.getSheets()[0]; 
      const data = sheet.getDataRange().getValues();
      const result = [];

      for (let i = 1; i < data.length; i++) {
        const row = data[i];
        if (row[1] && row[1].toString().trim() !== "") { 
          result.push({
            nama: row[8] ? row[8].toString() : "-",           // Kolom I: Nama
            nomor_kk: row[1] ? row[1].toString() : "-",       // Kolom B: No KK
            alamat: row[2] ? row[2].toString() : "-",         // Kolom C: Alamat
            waktu: row[3] ? row[3].toString() : "-",          // Kolom D: Waktu
            nik: row[9] ? row[9].toString() : "-",            // Kolom J: NIK
            jumlah_anggota: row[10] ? parseInt(row[10]) : 1,  // Kolom K: Jumlah
            status: row[17] ? row[17].toString() : "-"        // Kolom R: Status Hubungan
          });
        }
      }

      return ContentService.createTextOutput(JSON.stringify({
        status: 'success',
        data: result.reverse()
      })).setMimeType(ContentService.MimeType.JSON);
    } catch (err) {
      return ContentService.createTextOutput(JSON.stringify({status: 'error', message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
    }
  }
}

function doPost(e) {
  try {
    const data = JSON.parse(e.postData.contents);
    const ss = SpreadsheetApp.openById(data.spreadsheet_id);
    const sheet = ss.getSheets()[0];

    let fileUrl = "No Image";
    if (data.image_base64 && data.folder_id) {
      const folder = DriveApp.getFolderById(data.folder_id);
      const bytes = Utilities.base64Decode(data.image_base64.split(',')[1]);
      const file = folder.createFile(Utilities.newBlob(bytes, 'image/jpeg', data.filename + ".jpg"));
      fileUrl = file.getUrl();
    }

    // Simpan semua anggota keluarga ke baris masing-masing
    data.anggota_keluarga.forEach((member) => {
      const lastRow = sheet.getLastRow() + 1;
      sheet.getRange(lastRow, 1).setValue(member.nama.toUpperCase()); // A: Nama
      sheet.getRange(lastRow, 2).setValue("'" + data.nomor_kk);      // B: No KK
      sheet.getRange(lastRow, 3).setValue(data.alamat);             // C: Alamat
      sheet.getRange(lastRow, 4).setValue(new Date().toLocaleString('id-ID')); // D: Waktu
      sheet.getRange(lastRow, 5).setValue(fileUrl);                 // E: Foto

      sheet.getRange(lastRow, 9).setValue(member.nama.toUpperCase()); // I: Nama (Sesuai Permintaan)
      sheet.getRange(lastRow, 10).setValue("'" + member.nik);         // J: NIK
      sheet.getRange(lastRow, 11).setValue(data.anggota_keluarga.length); // K: Total Anggota
      sheet.getRange(lastRow, 18).setValue(member.status_hubungan);   // R: Status (Sesuai Permintaan)
    });

    return ContentService.createTextOutput(JSON.stringify({status: "success"})).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({status: "error", message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
  }
}`;

  return (
    <div className="max-w-5xl mx-auto space-y-8 animate-in fade-in duration-700">
      {/* Dashboard Stats */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex items-center gap-5">
          <div className="w-14 h-14 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-xl shadow-inner">
            <i className="fa-solid fa-folder-tree"></i>
          </div>
          <div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Total Baris</p>
            <h3 className="text-2xl font-black text-slate-900">{stats.totalEntries} <span className="text-xs text-slate-300 font-bold italic">Data</span></h3>
          </div>
        </div>
        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex items-center gap-5">
          <div className="w-14 h-14 bg-emerald-50 text-emerald-600 rounded-2xl flex items-center justify-center text-xl shadow-inner">
            <i className="fa-solid fa-id-card"></i>
          </div>
          <div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Dokumen KK</p>
            <h3 className="text-2xl font-black text-slate-900">{stats.uniqueKK} <span className="text-xs text-slate-300 font-bold italic">Berkas</span></h3>
          </div>
        </div>
        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex items-center gap-5">
          <div className="w-14 h-14 bg-amber-50 text-amber-600 rounded-2xl flex items-center justify-center text-xl shadow-inner">
            <i className="fa-solid fa-users"></i>
          </div>
          <div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Jiwa Terdata</p>
            <h3 className="text-2xl font-black text-slate-900">{stats.totalJiwa} <span className="text-xs text-slate-300 font-bold italic">Orang</span></h3>
          </div>
        </div>
      </div>

      <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
        <div className="relative flex-grow w-full group">
          <input 
            type="text" 
            placeholder="Cari Nama, No KK, atau Alamat..." 
            value={search} 
            onChange={(e) => setSearch(e.target.value)} 
            className="w-full pl-14 pr-6 py-5 bg-white border border-slate-100 rounded-[1.5rem] focus:ring-4 focus:ring-indigo-500/10 outline-none shadow-sm font-bold text-sm transition-all group-hover:border-indigo-200" 
          />
          <div className="absolute inset-y-0 left-0 pl-6 flex items-center pointer-events-none text-slate-300 group-hover:text-indigo-500 transition-colors">
            <i className="fa-solid fa-magnifying-glass text-lg"></i>
          </div>
        </div>
        <div className="flex gap-2 w-full sm:w-auto">
          <button onClick={() => setShowSetup(!showSetup)} className={`h-14 px-6 rounded-[1.5rem] flex items-center gap-3 transition-all ${showSetup ? 'bg-slate-900 text-white shadow-xl' : 'bg-white border border-slate-100 text-slate-400 hover:text-indigo-600 shadow-sm'}`}>
            <i className="fa-solid fa-terminal"></i>
            <span className="text-[10px] font-black uppercase tracking-widest">Config</span>
          </button>
          <button onClick={onRefresh} className="h-14 px-6 bg-white border border-slate-100 rounded-[1.5rem] flex items-center gap-3 text-slate-400 hover:text-indigo-600 transition-all shadow-sm">
            <i className={`fa-solid fa-sync-alt ${isLoading ? 'animate-spin' : ''}`}></i>
            <span className="text-[10px] font-black uppercase tracking-widest">Refresh</span>
          </button>
        </div>
      </div>

      {showSetup && (
        <div className="bg-slate-900 p-8 rounded-[2.5rem] shadow-2xl animate-in slide-in-from-top-4">
          <div className="flex items-center justify-between mb-6">
            <h4 className="text-indigo-400 text-xs font-black uppercase tracking-[0.2em]">Update Script Google Sheets (V7)</h4>
            <button onClick={() => { navigator.clipboard.writeText(appsScriptCode); alert("Script V7 disalin!"); }} className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-indigo-500 transition-all">Salin Script</button>
          </div>
          <p className="text-[10px] text-slate-400 font-bold uppercase mb-4 leading-relaxed border-l-2 border-indigo-500/30 pl-4">
            Script ini akan menyimpan <span className="text-indigo-300">setiap anggota keluarga</span> ke baris baru secara otomatis. <br/>
            Kolom I: Nama Anggota | Kolom C: Alamat | Kolom R: Status Hubungan.
          </p>
          <pre className="text-[10px] text-indigo-200/50 font-mono bg-black/30 p-5 rounded-2xl border border-white/5 overflow-x-auto max-h-40">{appsScriptCode}</pre>
        </div>
      )}

      <div className="space-y-4">
        {isLoading ? (
          <div className="py-24 text-center">
