import React, { useState, useMemo } from 'react';
import { KKData, KKMember, SavedEntry } from '../types';

interface KKFormProps {
  data: KKData;
  onSave: (finalData: KKData) => void;
  onCancel: () => void;
  isSaving?: boolean;
  existingEntries?: SavedEntry[];
}

const KKForm: React.FC<KKFormProps> = ({ data, onSave, onCancel, isSaving, existingEntries = [] }) => {
  const [formData, setFormData] = useState<KKData>(data);

  const isDuplicate = useMemo(() => {
    if (!formData.nomor_kk) return false;
    const currentNoKK = formData.nomor_kk.trim();
    return existingEntries.some(entry => entry.nomor_kk && entry.nomor_kk.trim() === currentNoKK);
  }, [formData.nomor_kk, existingEntries]);

  const handleHeaderChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleMemberChange = (index: number, e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    const newMembers = [...formData.anggota_keluarga];
    newMembers[index] = { ...newMembers[index], [name]: value };
    setFormData(prev => ({ ...prev, anggota_keluarga: newMembers }));
  };

  const addMember = () => {
    const newMember: KKMember = {
      nama: '', nik: '', jenis_kelamin: 'LAKI-LAKI', tempat_lahir: '', tanggal_lahir: '',
      agama: 'ISLAM', pendidikan: '', jenis_pekerjaan: '', status_perkawinan: 'BELUM KAWIN',
      status_hubungan: 'ANGGOTA KELUARGA', kewarganegaraan: 'WNI', nama_ayah: '', nama_ibu: ''
    };
    setFormData(prev => ({
      ...prev,
      anggota_keluarga: [...prev.anggota_keluarga, newMember]
    }));
  };

  const removeMember = (index: number) => {
    const newMembers = formData.anggota_keluarga.filter((_, i) => i !== index);
    setFormData(prev => ({ ...prev, anggota_keluarga: newMembers }));
  };

  const inputClass = "w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 outline-none text-sm transition-all font-semibold text-slate-700";
  const labelClass = "text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2 block pl-1";

  return (
    <div className="max-w-4xl mx-auto pb-44 animate-in fade-in slide-in-from-bottom-6 duration-700">
      {/* Warning Bar */}
      {isDuplicate && (
        <div className="mb-8 bg-amber-50 border border-amber-100 p-6 rounded-[2rem] flex items-center gap-6 shadow-sm">
          <div className="w-12 h-12 bg-amber-500 text-white rounded-2xl flex items-center justify-center shrink-0">
            <i className="fa-solid fa-triangle-exclamation text-xl"></i>
          </div>
          <div>
