        </div>

        <div className="flex items-center gap-4 mb-10 border-b border-slate-50 pb-8">
          <div className="w-14 h-14 bg-indigo-600 text-white rounded-2xl flex items-center justify-center text-xl shadow-xl shadow-indigo-100">
            <i className="fa-solid fa-folder-open"></i>
          </div>
          <div>
            <h4 className="font-black text-slate-900 uppercase italic tracking-tighter text-xl">Verifikasi Dokumen Utama</h4>
