      };

      await fetch(WEB_APP_URL, {
        method: 'POST',
        mode: 'no-cors',
        body: JSON.stringify(payload),
      });

      // Optimistic Update UI
      setState(AppState.SAVED);
      setTimeout(fetchHistory, 4000); // Tunggu server G-Apps Script memproses
    } catch (err) {
      setError("Kesalahan saat menyimpan.");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col font-sans">
