                  <span className="text-[10px] font-black text-indigo-500 uppercase tracking-[0.4em] block mb-2">Automated Extraction System</span>
                  <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase italic">SMART <span className="text-indigo-600">INPUT KK</span></h2>
                  <div className="w-16 h-1 bg-indigo-600 mx-auto mt-4 rounded-full"></div>
                </div>
                <FileUpload onFileSelect={handleFileSelect} isLoading={false} />
              </div>
            )}

            {state === AppState.SCANNING && (
              <div className="flex flex-col items-center justify-center py-32 animate-pulse">
                <div className="relative w-32 h-32 mb-10">
                  <div className="absolute inset-0 border-[6px] border-indigo-50 rounded-[2.5rem]"></div>
                  <div className="absolute inset-0 border-[6px] border-indigo-600 border-t-transparent rounded-[2.5rem] animate-spin"></div>
