import { GoogleGenAI, Type } from "@google/genai";
import { KKData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const kkSchema = {
  type: Type.OBJECT,
  properties: {
    nomor_kk: { type: Type.STRING, description: "Nomor Kartu Keluarga (16 digit)" },
    alamat: { type: Type.STRING, description: "Alamat lengkap" },
    rt_rw: { type: Type.STRING, description: "RT/RW" },
    kode_pos: { type: Type.STRING, description: "Kode Pos" },
    desa_kelurahan: { type: Type.STRING },
    kecamatan: { type: Type.STRING },
    kabupaten_kota: { type: Type.STRING },
    provinsi: { type: Type.STRING },
    anggota_keluarga: {
      type: Type.ARRAY,
      description: "Daftar seluruh anggota keluarga yang tercantum dalam tabel",
      items: {
        type: Type.OBJECT,
        properties: {
          nama: { type: Type.STRING, description: "Nama Lengkap" },
          nik: { type: Type.STRING, description: "NIK (16 digit)" },
          jenis_kelamin: { type: Type.STRING },
          tempat_lahir: { type: Type.STRING },
          tanggal_lahir: { type: Type.STRING, description: "Format: DD-MM-YYYY" },
          agama: { type: Type.STRING },
          pendidikan: { type: Type.STRING },
          jenis_pekerjaan: { type: Type.STRING },
          status_perkawinan: { type: Type.STRING },
          status_hubungan: { type: Type.STRING, description: "Status Hubungan Dalam Keluarga" },
          kewarganegaraan: { type: Type.STRING },
          nama_ayah: { type: Type.STRING, description: "Nama Lengkap Ayah" },
          nama_ibu: { type: Type.STRING, description: "Nama Lengkap Ibu" },
        },
        required: ["nama", "nik", "status_hubungan", "nama_ayah", "nama_ibu"]
      },
    },
  },
  required: ["nomor_kk", "anggota_keluarga"],
};

export const extractKKData = async (base64Image: string): Promise<KKData> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: [
        {
          parts: [
            {
              inlineData: {
                mimeType: "image/jpeg",
                data: base64Image.split(",")[1],
              },
            },
            {
              text: `TUGAS: Lakukan ekstraksi data SANGAT TELITI dari dokumen Kartu Keluarga ini.

INSTRUKSI KHUSUS:
1. Pindai tabel anggota keluarga dari baris pertama hingga terakhir. JANGAN ADA YANG TERLEWAT.
2. Ekstrak SEMUA KOLOM tanpa kecuali: Nama, NIK, Jenis Kelamin, Tempat/Tgl Lahir, Agama, Pendidikan, Pekerjaan, Status Kawin, Status Hubungan, Kewarganegaraan, Nama Ayah, dan Nama Ibu.
3. Pastikan kolom 'nama_ayah' dan 'nama_ibu' terisi sesuai yang tertera di bagian kanan tabel.
4. Perbaiki kapitalisasi menjadi UPPERCASE untuk Nama dan Alamat.
5. Jika teks buram, gunakan konteks dokumen untuk menebak dengan akurasi tinggi.
6. Kembalikan data dalam JSON murni sesuai skema.`,
            },
          ],
        },
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: kkSchema,
        temperature: 0.1, // Rendah untuk akurasi data fakta
      },
    });

    const text = response.text;
    if (!text) throw new Error("Gagal mengekstrak teks.");

    return JSON.parse(text) as KKData;
  } catch (error) {
    console.error("Gemini Extraction Error:", error);
    throw error;
  }
};

