import { GoogleGenAI, Type } from "@google/genai";
import { KKData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const kkSchema = {
  type: Type.OBJECT,
  properties: {
    nomor_kk: { type: Type.STRING, description: "Nomor Kartu Keluarga (16 digit)" },
    alamat: { type: Type.STRING },
    rt_rw: { type: Type.STRING },
    kode_pos: { type: Type.STRING },
    desa_kelurahan: { type: Type.STRING },
    kecamatan: { type: Type.STRING },
    kabupaten_kota: { type: Type.STRING },
    provinsi: { type: Type.STRING },
    anggota_keluarga: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          nama: { type: Type.STRING },
          nik: { type: Type.STRING },
          jenis_kelamin: { type: Type.STRING },
          tempat_lahir: { type: Type.STRING },
          tanggal_lahir: { type: Type.STRING },
          agama: { type: Type.STRING },
          pendidikan: { type: Type.STRING },
          jenis_pekerjaan: { type: Type.STRING },
          status_perkawinan: { type: Type.STRING },
          status_hubungan: { type: Type.STRING },
          kewarganegaraan: { type: Type.STRING, defaultValue: "WNI" },
          nama_ayah: { type: Type.STRING },
          nama_ibu: { type: Type.STRING },
        },
        required: ["nama", "nik", "nama_ayah", "nama_ibu"]
      },
    },
  },
  required: ["nomor_kk", "anggota_keluarga"],
};

export const extractKKData = async (base64Image: string): Promise<KKData> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: [
        {
          parts: [
            {
              inlineData: { mimeType: "image/jpeg", data: base64Image.split(",")[1] },
            },
            {
              text: `EKSTRAKSI DATA KK LENGKAP:
1. Pindai seluruh tabel dari Kolom Nama (1) sampai Kolom Nama Ibu (16).
2. Pastikan data HEADER terisi: Provinsi, Kabupaten/Kota, Kecamatan, Desa, Alamat, No KK.
3. Untuk setiap anggota keluarga, pastikan Nama Ayah dan Nama Ibu terekstrak dengan benar.
4. Format tanggal lahir: DD-MM-YYYY.
5. Gunakan UPPERCASE untuk semua field teks.`,
            },
          ],
        },
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: kkSchema,
        temperature: 0.1,
      },
    });

    return JSON.parse(response.text) as KKData;
  } catch (error) {
    console.error("Gemini Error:", error);
    throw error;
  }
};

