      sheet.getRange(lastRow, 8).setValue(data.kode_pos);           // H: KODE POS
      sheet.getRange(lastRow, 9).setValue(member.nama.toUpperCase()); // I: NAMA
      sheet.getRange(lastRow, 10).setValue("'" + member.nik);        // J: NOMER NIK
      sheet.getRange(lastRow, 11).setValue(member.jenis_kelamin);    // K: JENIS KELAMIN
      sheet.getRange(lastRow, 12).setValue(member.tempat_lahir);     // L: TEMPAT LAHIR
      sheet.getRange(lastRow, 13).setValue(member.tanggal_lahir);    // M: TANGGAL LAHIR
      sheet.getRange(lastRow, 14).setValue(member.agama);            // N: AGAMA
      sheet.getRange(lastRow, 15).setValue(member.pendidikan);       // O: PENDIDIKAN
