      sheet.getRange(lastRow, 21).setValue(member.nama_ibu.toUpperCase());  // U: NAMA IBU
      sheet.getRange(lastRow, 22).setValue(fileUrl);                 // V: LINK KK
      sheet.getRange(lastRow, 23).setValue(new Date().toLocaleString('id-ID')); // W: TIME STAMP
    });

    return ContentService.createTextOutput(JSON.stringify({status: "success"})).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({status: "error", message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
  }
}`;

  return (
    <div className="max-w-6xl mx-auto space-y-8 pb-40">
