    provinsi: { type: Type.STRING },
    anggota_keluarga: {
      type: Type.ARRAY,
      description: "Daftar semua individu dalam tabel anggota keluarga.",
      items: {
        type: Type.OBJECT,
        properties: {
          nama: { type: Type.STRING, description: "Nama lengkap sesuai kolom 1" },
          nik: { type: Type.STRING, description: "NIK sesuai kolom 2" },
          jenis_kelamin: { type: Type.STRING, description: "Kolom 3" },
          tempat_lahir: { type: Type.STRING, description: "Kolom 4" },
          tanggal_lahir: { type: Type.STRING, description: "Kolom 5 (DD-MM-YYYY)" },
          agama: { type: Type.STRING, description: "Kolom 6" },
          pendidikan: { type: Type.STRING, description: "Kolom 7" },
          jenis_pekerjaan: { type: Type.STRING, description: "Kolom 8" },
          status_perkawinan: { type: Type.STRING, description: "Kolom 9" },
          status_hubungan: { type: Type.STRING, description: "Kolom 10" },
          kewarganegaraan: { type: Type.STRING, description: "Kolom 11" },
          nama_ayah: { type: Type.STRING, description: "Nama Ayah - biasanya di bagian tabel kedua atau kolom 15" },
          nama_ibu: { type: Type.STRING, description: "Nama Ibu - biasanya di bagian tabel kedua atau kolom 16" },
        },
        required: ["nama", "nik", "status_hubungan", "nama_ayah", "nama_ibu"]
      },
    },
  },
  required: ["nomor_kk", "anggota_keluarga"],
};

export const extractKKData = async (base64Image: string): Promise<KKData> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: [
        {
          parts: [
            {
              inlineData: { 
                mimeType: "image/jpeg", 
                data: base64Image.split(",")[1] 
              },
            },
            {
              text: `TUGAS: Ekstraksi data Kartu Keluarga dengan tingkat presisi 100%.

INSTRUKSI DETAIL:
1. Identifikasi HEADER: No KK, Alamat, RT/RW, Desa, Kecamatan, Kabupaten/Kota, Provinsi, Kode Pos.
2. Identifikasi TABEL: Pindai seluruh baris anggota keluarga. JANGAN ADA YANG TERLEWAT.
3. EKSTRAKSI KOLOM:
   - Nama & NIK (Wajib).
   - TTL, Jenis Kelamin, Agama, Pendidikan, Pekerjaan.
   - Status Perkawinan & Hubungan Keluarga.
   - Kewarganegaraan (WNI/WNA).
   - NAMA AYAH & NAMA IBU (Sangat penting, biasanya di tabel bagian kanan).
4. VALIDASI: Pastikan jumlah anggota keluarga yang diekstrak sesuai dengan jumlah baris yang terlihat di foto.
5. FORMAT: Kembalikan data dalam format JSON yang valid. Semua teks harus UPPERCASE.`,
            },
          ],
        },
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: kkSchema,
        temperature: 0.1,
      },
    });

    const responseText = response.text;
    if (!responseText) {
      throw new Error("Model tidak mengembalikan teks.");
    }

    return JSON.parse(responseText) as KKData;
  } catch (error) {
    console.error("Gemini Extraction Error:", error);
    throw error;
  }
};

