              className="w-full py-5 bg-white border-2 border-slate-100 text-slate-400 rounded-2xl font-black uppercase text-xs hover:bg-slate-50 active:scale-95 transition-all"
            >
              Batalkan & Periksa Kembali
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

