const DatabaseView: React.FC<DatabaseViewProps> = ({ entries, isLoading, hasError, spreadsheetId, onRefresh, onBack }) => {
  const [search, setSearch] = useState("");
  const [showSetup, setShowSetup] = useState(false);
  const [selectedEntry, setSelectedEntry] = useState<SavedEntry | null>(null);

  const filteredEntries = entries.filter(entry => 
    (entry.nama || "").toLowerCase().includes(search.toLowerCase()) || 
    (entry.nomor_kk || "").toLowerCase().includes(search.toLowerCase()) ||
    (entry.nik || "").toLowerCase().includes(search.toLowerCase())
  );

  const appsScriptCode = `function doGet(e) {
  const ssId = e.parameter.spreadsheet_id;
  const action = e.parameter.action;

  if (action === 'read') {
    try {
      const ss = SpreadsheetApp.openById(ssId);
      const sheet = ss.getSheets()[0]; 
      const data = sheet.getDataRange().getValues();
      const result = [];

      for (let i = 1; i < data.length; i++) {
        const row = data[i];
        if (row[0]) { // Cek Kolom A
          result.push({
            nomor_kk: row[0] ? row[0].toString() : "-",        // A
            alamat: row[1] ? row[1].toString() : "-",          // B
            rt_rw: row[2] ? row[2].toString() : "-",           // C
            desa_kelurahan: row[3] ? row[3].toString() : "-",  // D
            kecamatan: row[4] ? row[4].toString() : "-",       // E
            kabupaten_kota: row[5] ? row[5].toString() : "-",  // F
            provinsi: row[6] ? row[6].toString() : "-",        // G
            kode_pos: row[7] ? row[7].toString() : "-",        // H
            nama: row[8] ? row[8].toString() : "-",            // I
            nik: row[9] ? row[9].toString() : "-",             // J
            jenis_kelamin: row[10] ? row[10].toString() : "-", // K
            tempat_lahir: row[11] ? row[11].toString() : "-",  // L
            tanggal_lahir: row[12] ? row[12].toString() : "-", // M
            agama: row[13] ? row[13].toString() : "-",         // N
            pendidikan: row[14] ? row[14].toString() : "-",    // O
            jenis_pekerjaan: row[15] ? row[15].toString() : "-",// P
            status_perkawinan: row[16] ? row[16].toString() : "-",// Q
            status_hubungan: row[17] ? row[17].toString() : "-",// R
            kewarganegaraan: row[18] ? row[18].toString() : "-",// S
            nama_ayah: row[19] ? row[19].toString() : "-",     // T
            nama_ibu: row[20] ? row[20].toString() : "-",      // U
            foto_url: row[21] ? row[21].toString() : "No Image",// V
            waktu: row[22] ? row[22].toString() : "-"          // W
          });
        }
      }
      return ContentService.createTextOutput(JSON.stringify({status: 'success', data: result.reverse()})).setMimeType(ContentService.MimeType.JSON);
    } catch (err) {
      return ContentService.createTextOutput(JSON.stringify({status: 'error', message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
    }
  }
}

function doPost(e) {
  try {
    const data = JSON.parse(e.postData.contents);
    const ss = SpreadsheetApp.openById(data.spreadsheet_id);
    const sheet = ss.getSheets()[0];

    let fileUrl = "No Image";
    if (data.image_base64 && data.folder_id) {
      const folder = DriveApp.getFolderById(data.folder_id);
      const bytes = Utilities.base64Decode(data.image_base64.split(',')[1]);
      const file = folder.createFile(Utilities.newBlob(bytes, 'image/jpeg', data.filename + ".jpg"));
      fileUrl = file.getUrl();
    }

    data.anggota_keluarga.forEach((member) => {
      const lastRow = sheet.getLastRow() + 1;
      sheet.getRange(lastRow, 1).setValue("'" + data.nomor_kk);      
      sheet.getRange(lastRow, 2).setValue(data.alamat);             
      sheet.getRange(lastRow, 3).setValue(data.rt_rw);              
      sheet.getRange(lastRow, 4).setValue(data.desa_kelurahan);     
      sheet.getRange(lastRow, 5).setValue(data.kecamatan);          
      sheet.getRange(lastRow, 6).setValue(data.kabupaten_kota);     
      sheet.getRange(lastRow, 7).setValue(data.provinsi);           
      sheet.getRange(lastRow, 8).setValue(data.kode_pos);           
      sheet.getRange(lastRow, 9).setValue(member.nama.toUpperCase()); 
      sheet.getRange(lastRow, 10).setValue("'" + member.nik);        
      sheet.getRange(lastRow, 11).setValue(member.jenis_kelamin);    
      sheet.getRange(lastRow, 12).setValue(member.tempat_lahir);     
      sheet.getRange(lastRow, 13).setValue(member.tanggal_lahir);    
      sheet.getRange(lastRow, 14).setValue(member.agama);            
      sheet.getRange(lastRow, 15).setValue(member.pendidikan);       
      sheet.getRange(lastRow, 16).setValue(member.jenis_pekerjaan);  
      sheet.getRange(lastRow, 17).setValue(member.status_perkawinan);
      sheet.getRange(lastRow, 18).setValue(member.status_hubungan);  
      sheet.getRange(lastRow, 19).setValue(member.kewarganegaraan); 
      sheet.getRange(lastRow, 20).setValue(member.nama_ayah.toUpperCase()); 
      sheet.getRange(lastRow, 21).setValue(member.nama_ibu.toUpperCase());  
      sheet.getRange(lastRow, 22).setValue(fileUrl);                 
      sheet.getRange(lastRow, 23).setValue(new Date().toLocaleString('id-ID')); 
    });

    return ContentService.createTextOutput(JSON.stringify({status: "success"})).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({status: "error", message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
  }
}`;

  return (
    <div className="max-w-6xl mx-auto space-y-8 pb-40">
