const DatabaseView: React.FC<DatabaseViewProps> = ({ entries, isLoading, hasError, spreadsheetId, onRefresh, onBack, onDelete }) => {
  const [search, setSearch] = useState("");
  const [showSetup, setShowSetup] = useState(false);
  const [selectedEntry, setSelectedEntry] = useState<SavedEntry | null>(null);
  const [isDeleting, setIsDeleting] = useState<string | null>(null);

  const filteredEntries = entries.filter(entry => 
    (entry.nama || "").toLowerCase().includes(search.toLowerCase()) || 
    (entry.nomor_kk || "").toLowerCase().includes(search.toLowerCase()) ||
    (entry.nik || "").toLowerCase().includes(search.toLowerCase())
  );

  const stats = {
    total: entries.length,
    male: entries.filter(e => (e.jenis_kelamin || "").toUpperCase().startsWith('L')).length,
    female: entries.filter(e => (e.jenis_kelamin || "").toUpperCase().startsWith('P')).length
  };

  const handleExportCSV = () => {
    if (entries.length === 0) return;
    const headers = Object.keys(entries[0]).join(",");
    const rows = entries.map(entry => Object.values(entry).map(v => `"${v}"`).join(",")).join("\n");
    const csvContent = "data:text/csv;charset=utf-8," + headers + "\n" + rows;
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `Database_KK_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleDeleteClick = async (e: React.MouseEvent, entry: SavedEntry) => {
    e.stopPropagation();
    if (window.confirm(`Hapus data ${entry.nama} (NIK: ${entry.nik}) secara permanen?`)) {
      setIsDeleting(entry.nik);
      await onDelete(entry.nik, entry.waktu);
      setIsDeleting(null);
    }
  };

  const appsScriptCode = `function doGet(e) {
  const ssId = e.parameter.spreadsheet_id;
  const action = e.parameter.action;

  if (action === 'read') {
    try {
      const ss = SpreadsheetApp.openById(ssId);
      const sheet = ss.getSheets()[0]; 
      const data = sheet.getDataRange().getValues();
      const result = [];

      for (let i = 1; i < data.length; i++) {
        const row = data[i];
        if (row[0]) {
          result.push({
            nomor_kk: row[0] ? row[0].toString() : "-",        
            alamat: row[1] ? row[1].toString() : "-",          
            rt_rw: row[2] ? row[2].toString() : "-",           
            desa_kelurahan: row[3] ? row[3].toString() : "-",  
            kecamatan: row[4] ? row[4].toString() : "-",       
            kabupaten_kota: row[5] ? row[5].toString() : "-",  
            provinsi: row[6] ? row[6].toString() : "-",        
            kode_pos: row[7] ? row[7].toString() : "-",        
            nama: row[8] ? row[8].toString() : "-",            
            nik: row[9] ? row[9].toString() : "-",             
            jenis_kelamin: row[10] ? row[10].toString() : "-", 
            tempat_lahir: row[11] ? row[11].toString() : "-",  
            tanggal_lahir: row[12] ? row[12].toString() : "-", 
            agama: row[13] ? row[13].toString() : "-",         
            pendidikan: row[14] ? row[14].toString() : "-",    
            jenis_pekerjaan: row[15] ? row[15].toString() : "-",
            status_perkawinan: row[16] ? row[16].toString() : "-",
            status_hubungan: row[17] ? row[17].toString() : "-",
            kewarganegaraan: row[18] ? row[18].toString() : "-",
            nama_ayah: row[19] ? row[19].toString() : "-",     
            nama_ibu: row[20] ? row[20].toString() : "-",      
            foto_url: row[21] ? row[21].toString() : "No Image",
            waktu: row[22] ? row[22].toString() : "-"          
          });
        }
      }
      return ContentService.createTextOutput(JSON.stringify({status: 'success', data: result.reverse()})).setMimeType(ContentService.MimeType.JSON);
    } catch (err) {
      return ContentService.createTextOutput(JSON.stringify({status: 'error', message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
    }
  }
}

function doPost(e) {
  try {
    const data = JSON.parse(e.postData.contents);
    const ss = SpreadsheetApp.openById(data.spreadsheet_id);
    const sheet = ss.getSheets()[0];

    if (data.action === 'delete') {
      const nikToDelete = data.nik;
      const waktuToDelete = data.waktu;
      const values = sheet.getDataRange().getValues();

      for (let i = values.length - 1; i >= 1; i--) {
        const nikInSheet = values[i][9] ? values[i][9].toString().replace("'", "") : "";
        const waktuInSheet = values[i][22] ? values[i][22].toString() : "";

        if (nikInSheet === nikToDelete && (waktuInSheet === waktuToDelete || waktuToDelete === "FORCE")) {
          sheet.deleteRow(i + 1);
        }
      }
      return ContentService.createTextOutput(JSON.stringify({status: "success"})).setMimeType(ContentService.MimeType.JSON);
    }

    let fileUrl = "No Image";
    if (data.image_base64 && data.folder_id) {
      const folder = DriveApp.getFolderById(data.folder_id);
      const bytes = Utilities.base64Decode(data.image_base64.split(',')[1]);
      const file = folder.createFile(Utilities.newBlob(bytes, 'image/jpeg', data.filename + ".jpg"));
      fileUrl = file.getUrl();
    }

    data.anggota_keluarga.forEach((member) => {
      const lastRow = sheet.getLastRow() + 1;
      sheet.getRange(lastRow, 1).setValue("'" + data.nomor_kk);      
      sheet.getRange(lastRow, 2).setValue(data.alamat);             
      sheet.getRange(lastRow, 3).setValue(data.rt_rw);              
      sheet.getRange(lastRow, 4).setValue(data.desa_kelurahan);     
      sheet.getRange(lastRow, 5).setValue(data.kecamatan);          
      sheet.getRange(lastRow, 6).setValue(data.kabupaten_kota);     
      sheet.getRange(lastRow, 7).setValue(data.provinsi);           
      sheet.getRange(lastRow, 8).setValue(data.kode_pos);           
      sheet.getRange(lastRow, 9).setValue(member.nama.toUpperCase()); 
      sheet.getRange(lastRow, 10).setValue("'" + member.nik);        
      sheet.getRange(lastRow, 11).setValue(member.jenis_kelamin);    
      sheet.getRange(lastRow, 12).setValue(member.tempat_lahir);     
      sheet.getRange(lastRow, 13).setValue(member.tanggal_lahir);    
      sheet.getRange(lastRow, 14).setValue(member.agama);            
      sheet.getRange(lastRow, 15).setValue(member.pendidikan);       
      sheet.getRange(lastRow, 16).setValue(member.jenis_pekerjaan);  
      sheet.getRange(lastRow, 17).setValue(member.status_perkawinan);
      sheet.getRange(lastRow, 18).setValue(member.status_hubungan);  
      sheet.getRange(lastRow, 19).setValue(member.kewarganegaraan); 
      sheet.getRange(lastRow, 20).setValue(member.nama_ayah.toUpperCase()); 
      sheet.getRange(lastRow, 21).setValue(member.nama_ibu.toUpperCase());  
      sheet.getRange(lastRow, 22).setValue(fileUrl);                 
      sheet.getRange(lastRow, 23).setValue(new Date().toLocaleString('id-ID')); 
    });

    return ContentService.createTextOutput(JSON.stringify({status: "success"})).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({status: "error", message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
  }
}`;

  return (
    <div className="max-w-6xl mx-auto space-y-8 pb-40">
      <div className="bg-slate-900 rounded-[3rem] p-10 text-white shadow-2xl relative overflow-hidden">
        <div className="relative z-10">
          <h2 className="text-2xl font-black tracking-tight italic uppercase">RIWAYAT <span className="text-indigo-400">DATABASE KK</span></h2>
          <div className="flex gap-8 mt-6">
            <div className="bg-white/5 backdrop-blur px-6 py-4 rounded-2xl border border-white/10">
              <p className="text-[9px] uppercase font-black text-indigo-400 tracking-widest mb-1">Total Jiwa</p>
              <h4 className="text-2xl font-black">{stats.total}</h4>
            </div>
            <div className="bg-white/5 backdrop-blur px-6 py-4 rounded-2xl border border-white/10">
              <p className="text-[9px] uppercase font-black text-blue-400 tracking-widest mb-1">Laki-Laki</p>
              <h4 className="text-2xl font-black">{stats.male}</h4>
            </div>
            <div className="bg-white/5 backdrop-blur px-6 py-4 rounded-2xl border border-white/10">
              <p className="text-[9px] uppercase font-black text-pink-400 tracking-widest mb-1">Perempuan</p>
              <h4 className="text-2xl font-black">{stats.female}</h4>
            </div>
          </div>
        </div>
        <div className="absolute top-0 right-0 p-12 opacity-10 pointer-events-none">
          <i className="fa-solid fa-database text-9xl"></i>
        </div>

        <div className="absolute top-10 right-10 flex gap-3">
            <button onClick={handleExportCSV} className="bg-green-600 hover:bg-green-700 text-white px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center gap-2 shadow-xl shadow-green-900/20">
              <i className="fa-solid fa-file-excel text-sm"></i> Export CSV
            </button>
        </div>
      </div>

      <div className="flex gap-4">
        <div className="relative flex-1">
          <input 
            type="text" 
            placeholder="Cari Nama, NIK, atau No KK..." 
            value={search} 
            onChange={(e) => setSearch(e.target.value)} 
            className="w-full pl-14 pr-8 py-5 bg-white border border-slate-200 rounded-3xl shadow-sm outline-none focus:ring-4 focus:ring-indigo-50 font-medium" 
          />
          <div className="absolute inset-y-0 left-0 pl-6 flex items-center text-slate-300">
            <i className="fa-solid fa-search"></i>
          </div>
        </div>
        <button onClick={() => setShowSetup(!showSetup)} className="w-16 h-[60px] bg-white border border-slate-200 rounded-3xl text-slate-400 hover:text-indigo-600 transition-colors">
          <i className="fa-solid fa-gear"></i>
        </button>
        <button onClick={onRefresh} className="w-16 h-[60px] bg-white border border-slate-200 rounded-3xl text-slate-400 hover:text-indigo-600 transition-colors">
          <i className={`fa-solid fa-sync ${isLoading ? 'animate-spin' : ''}`}></i>
        </button>
      </div>

      {showSetup && (
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl animate-in zoom-in-95">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h5 className="font-black text-xs uppercase tracking-widest text-slate-800">Apps Script (V12 - Full CRUD Sync)</h5>
              <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">Gunakan versi ini agar fitur HAPUS bisa bekerja</p>
            </div>
            <button onClick={() => { navigator.clipboard.writeText(appsScriptCode); alert("Script V12 disalin!"); }} className="bg-indigo-600 text-white px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-indigo-700 active:scale-95 transition-all">Salin Script</button>
          </div>
          <pre className="text-[9px] text-slate-500 font-mono bg-slate-50 p-6 rounded-2xl max-h-48 overflow-y-auto border border-slate-100">{appsScriptCode}</pre>
        </div>
      )}

      <div className="grid grid-cols-1 gap-4">
        {isLoading ? (
          <div className="py-24 text-center bg-white rounded-[3rem] border border-slate-50">
            <i className="fa-solid fa-circle-notch animate-spin text-4xl text-indigo-600 mb-4"></i>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Sinkronisasi Cloud...</p>
          </div>
