              onClick={() => setSelectedEntry(e)}
              className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col md:flex-row md:items-center gap-6 group hover:shadow-xl hover:border-indigo-100 transition-all cursor-pointer active:scale-[0.99]"
            >
