                    {e.status_hubungan}
                  </span>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-y-2 gap-x-8">
                  <div className="flex flex-col">
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">NIK</span>
                    <span className="text-xs font-mono font-bold text-slate-700 tracking-wider">{e.nik}</span>
                  </div>
                  <div className="flex flex-col">
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">KK</span>
                    <span className="text-xs font-mono font-bold text-indigo-600 tracking-wider">{e.nomor_kk}</span>
                  </div>
                  <div className="flex flex-col">
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Gender</span>
                    <span className="text-xs font-bold text-slate-700 uppercase">{e.jenis_kelamin}</span>
                  </div>
                </div>
              </div>

              <div className="flex items-center gap-4 border-t md:border-t-0 md:border-l border-slate-100 pt-4 md:pt-0 md:pl-8">
                <div className="md:text-right hidden sm:block">
                    <p className="text-[10px] font-black text-slate-900 uppercase tracking-tighter whitespace-nowrap">{e.waktu}</p>
                    <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest opacity-60">Terinput</p>
                </div>
                <button 
                  onClick={(event) => handleDeleteClick(event, e)}
                  disabled={isDeleting === e.nik}
                  className="w-12 h-12 rounded-2xl bg-red-50 text-red-400 hover:bg-red-500 hover:text-white transition-all flex items-center justify-center shadow-inner"
                >
                  {isDeleting === e.nik ? <i className="fa-solid fa-spinner animate-spin"></i> : <i className="fa-solid fa-trash-can"></i>}
                </button>
              </div>
            </div>
          ))
        ) : (
          <div className="py-32 bg-white rounded-[3rem] border-2 border-dashed border-slate-100 text-center">
            <p className="text-slate-400 font-black uppercase tracking-[0.3em] text-xs">Data Tidak Ditemukan</p>
          </div>
        )}
      </div>

      {selectedEntry && (
        <EntryDetailModal 
          entry={selectedEntry} 
          onClose={() => setSelectedEntry(null)} 
        />
      )}
    </div>
  );
};

export default DatabaseView;

import React, { useState, useEffect, useCallback } from 'react';
import Header from './components/Header';
import FileUpload from './components/FileUpload';
import KKForm from './components/KKForm';
import SuccessState from './components/SuccessState';
import DatabaseView from './components/DatabaseView';
import DuplicateWarning from './components/DuplicateWarning';
import { extractKKData } from './services/geminiService';
import { AppState, KKData, SavedEntry } from './types';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'scanner' | 'history'>('scanner');
  const [state, setState] = useState<AppState>(AppState.IDLE);
  const [kkData, setKkData] = useState<KKData | null>(null);
  const [currentImageBase64, setCurrentImageBase64] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [isLoadingHistory, setIsLoadingHistory] = useState(false);
  const [savedHistory, setSavedHistory] = useState<SavedEntry[]>([]);
  const [fetchError, setFetchError] = useState<boolean>(false);

  const [showDuplicateWarning, setShowDuplicateWarning] = useState(false);
  const [pendingSaveData, setPendingSaveData] = useState<KKData | null>(null);

  const WEB_APP_URL = "https://script.google.com/macros/s/AKfycbzOmh5bwfECB9BduRVZU77iNkDWJnmHRMIU_8t9HlJ0imy8NL8xjvKPfM_2cbBFiWmchg/exec";
  const SPREADSHEET_ID = "1mIpV1syBF1GslK1A9l9dYvw4TDO0Yf98sO2wtejQkqs";
  const FOLDER_ID = "1suJP423Z_vZbZV7zlp61_n2uNflqkfGB";

  const fetchHistory = useCallback(async () => {
    setIsLoadingHistory(true);
    setFetchError(false);
    try {
      const cacheBuster = `t=${Date.now()}`;
      const url = `${WEB_APP_URL}?spreadsheet_id=${SPREADSHEET_ID}&action=read&${cacheBuster}`;
      const response = await fetch(url);
      const result = await response.json();

      if (result && result.status === 'success' && Array.isArray(result.data)) {
        setSavedHistory(result.data);
        localStorage.setItem('kk_v12_history', JSON.stringify(result.data));
      }
    } catch (err) {
      console.error("Fetch Error:", err);
      setFetchError(true);
      const local = localStorage.getItem('kk_v12_history');
      if (local) setSavedHistory(JSON.parse(local));
    } finally {
      setIsLoadingHistory(false);
    }
  }, [WEB_APP_URL, SPREADSHEET_ID]);

  useEffect(() => {
    fetchHistory();
  }, [fetchHistory]);

  const handleFileSelect = async (base64: string) => {
    setState(AppState.SCANNING);
    setCurrentImageBase64(base64);
    setError(null);
    try {
      const data = await extractKKData(base64);
      setKkData(data);
      setState(AppState.REVIEWING);
    } catch (err) {
      setError("Gagal mengekstrak data. Pastikan foto KK jelas.");
      setState(AppState.IDLE);
    }
  };

  const executeSave = async (finalData: KKData) => {
    setIsSaving(true);
    setError(null);
    try {
      const kepalaKeluarga = finalData.anggota_keluarga.find(
        m => m.status_hubungan.toUpperCase().includes("KEPALA")
      ) || finalData.anggota_keluarga[0];

      const payload = {
        spreadsheet_id: SPREADSHEET_ID,
        folder_id: FOLDER_ID,
        image_base64: currentImageBase64,
        filename: `KK_${kepalaKeluarga?.nama.toUpperCase().replace(/\s+/g, '_')}_${Date.now()}`,
        jumlah_anggota: finalData.anggota_keluarga.length,
        ...finalData
      };

      await fetch(WEB_APP_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });

      setState(AppState.SAVED);
      setTimeout(fetchHistory, 3000); 
    } catch (err) {
      setError("Gagal menyimpan data. Silakan coba lagi.");
    } finally {
      setIsSaving(false);
      setPendingSaveData(null);
      setShowDuplicateWarning(false);
    }
  };

  const handleSaveAttempt = (finalData: KKData) => {
    const cleanNewKK = finalData.nomor_kk.replace(/\D/g, '');
    const isDuplicate = savedHistory.some(entry => {
      const cleanExistingKK = (entry.nomor_kk || "").replace(/\D/g, '');
      return cleanExistingKK === cleanNewKK && cleanNewKK !== "";
    });

    if (isDuplicate) {
      setPendingSaveData(finalData);
      setShowDuplicateWarning(true);
    } else {
      executeSave(finalData);
    }
  };

  const handleDelete = async (nik: string, waktu: string) => {
    try {
      await fetch(WEB_APP_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'delete',
          spreadsheet_id: SPREADSHEET_ID,
          nik: nik,
          waktu: waktu
        }),
      });
      // Optimistic UI update
      setSavedHistory(prev => prev.filter(e => e.nik !== nik));
      // Real refresh
      setTimeout(fetchHistory, 1500);
    } catch (err) {
      alert("Gagal menghapus data dari server.");
    }
  };

  const resetApp = () => {
    setState(AppState.IDLE);
    setKkData(null);
    setCurrentImageBase64(null);
    setError(null);
    setActiveTab('scanner');
  };

  return (
    <div className="min-h-screen bg-[#F8FAFC]">
      <Header />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10">
        <div className="flex justify-center mb-12">
          <div className="bg-white p-2 rounded-[2rem] shadow-sm border border-slate-100 flex gap-2">
            <button 
              onClick={() => { setActiveTab('scanner'); setState(AppState.IDLE); }}
              className={`px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'scanner' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'text-slate-400 hover:text-slate-600'}`}
            >
              <i className="fa-solid fa-qrcode mr-2"></i> Input Data
            </button>
            <button 
              onClick={() => { setActiveTab('history'); setState(AppState.DATABASE); }}
              className={`px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'history' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'text-slate-400 hover:text-slate-600'}`}
            >
              <i className="fa-solid fa-list-check mr-2"></i> Riwayat Database
            </button>
          </div>
        </div>

        {activeTab === 'scanner' ? (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            {state === AppState.IDLE && (
              <FileUpload onFileSelect={handleFileSelect} isLoading={false} />
            )}

            {state === AppState.SCANNING && (
              <div className="max-w-xl mx-auto text-center py-20">
                <div className="relative mb-10">
                  <div className="w-32 h-32 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin mx-auto"></div>
                  <div className="absolute inset-0 flex items-center justify-center">
                    <i className="fa-solid fa-brain text-4xl text-indigo-600 animate-pulse"></i>
                  </div>
                </div>
                <h2 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter">AI Gemini Sedang <span className="text-indigo-600">Berpikir...</span></h2>
                <p className="text-slate-400 font-bold uppercase text-[10px] tracking-[0.3em] mt-4">Menganalisa Struktur Tabel Dokumen</p>
              </div>
            )}

            {state === AppState.REVIEWING && kkData && (
              <KKForm 
                data={kkData} 
                onSave={handleSaveAttempt} 
                onCancel={() => setState(AppState.IDLE)} 
                isSaving={isSaving}
              />
            )}

            {state === AppState.SAVED && (
              <SuccessState onReset={resetApp} onViewDatabase={() => { setActiveTab('history'); setState(AppState.DATABASE); }} />
            )}

            {error && (
              <div className="max-w-xl mx-auto mt-8 p-6 bg-red-50 border border-red-100 rounded-3xl text-center">
                <i className="fa-solid fa-circle-exclamation text-red-500 text-2xl mb-3"></i>
                <p className="text-red-700 font-bold text-sm uppercase tracking-tight">{error}</p>
                <button onClick={() => setError(null)} className="mt-4 text-[10px] font-black uppercase text-red-400 tracking-widest hover:text-red-600 transition-colors">Tutup Peringatan</button>
              </div>
            )}
          </div>
        ) : (
          <DatabaseView 
            entries={savedHistory} 
            isLoading={isLoadingHistory} 
            hasError={fetchError}
            spreadsheetId={SPREADSHEET_ID}
            onRefresh={fetchHistory}
            onBack={() => setActiveTab('scanner')}
            onDelete={handleDelete}
          />
        )}
      </main>

      {showDuplicateWarning && pendingSaveData && (
        <DuplicateWarning 
          nomorKK={pendingSaveData.nomor_kk}
          onConfirm={() => executeSave(pendingSaveData)}
          onCancel={() => {
            setShowDuplicateWarning(false);
            setPendingSaveData(null);
          }}
        />
      )}

      <footer className="fixed bottom-0 left-0 right-0 p-8 pointer-events-none text-center">
        <div className="bg-white/80 backdrop-blur-md border border-slate-100 inline-flex items-center gap-4 px-8 py-3 rounded-full shadow-lg pointer-events-auto">
          <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Powered By</span>
          <div className="h-4 w-[1px] bg-slate-200"></div>
          <span className="text-[10px] font-black text-slate-900 tracking-tighter italic uppercase">Google Gemini <span className="text-indigo-600">AI</span></span>
        </div>
      </footer>
    </div>
  );
};

