import React, { useState } from 'react';

interface LoginProps {
  onLogin: (password: string) => Promise<boolean>;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [pin, setPin] = useState("");
  const [error, setError] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const handleInput = (val: string) => {
    if (pin.length < 6) {
      setPin(prev => prev + val);
      setError(false);
    }
  };

  const handleClear = () => setPin("");

  const handleSubmit = async () => {
    setIsLoading(true);
    const success = await onLogin(pin);
    if (!success) {
      setError(true);
      setPin("");
    }
    setIsLoading(false);
  };

  return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center p-6">
      <div className="w-full max-w-md animate-in fade-in zoom-in-95 duration-500">
        <div className="text-center mb-10">
          <div className="w-20 h-20 bg-indigo-600 rounded-3xl flex items-center justify-center text-white mx-auto mb-6 shadow-2xl shadow-indigo-500/20">
            <i className="fa-solid fa-shield-halved text-3xl"></i>
          </div>
          <h2 className="text-2xl font-black text-white uppercase italic tracking-tighter">Secure <span className="text-indigo-400">Portal</span></h2>
          <p className="text-slate-400 text-[10px] font-bold uppercase tracking-[0.3em] mt-2">Masukkan Sandi Akses Anda</p>
        </div>

        <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-[3rem] p-10 shadow-2xl">
          <div className="flex justify-center gap-4 mb-10">
            {[...Array(6)].map((_, i) => (
              <div 
                key={i} 
                className={`w-4 h-4 rounded-full border-2 transition-all duration-300 ${
                  pin.length > i 
                    ? 'bg-indigo-500 border-indigo-500 scale-125' 
                    : error ? 'border-red-500 bg-red-500/20' : 'border-white/20'
                }`}
              ></div>
            ))}
          </div>

          <div className="grid grid-cols-3 gap-4 mb-8">
            {[1, 2, 3, 4, 5, 6, 7, 8, 9].map(num => (
              <button 
                key={num} 
                onClick={() => handleInput(num.toString())}
                className="h-16 rounded-2xl bg-white/5 hover:bg-white/10 text-white font-black text-xl transition-all active:scale-90 border border-white/5"
              >
                {num}
              </button>
            ))}
            <button onClick={handleClear} className="h-16 rounded-2xl bg-red-500/10 hover:bg-red-500/20 text-red-400 font-black text-sm transition-all active:scale-90 border border-red-500/10">CLR</button>
            <button onClick={() => handleInput("0")} className="h-16 rounded-2xl bg-white/5 hover:bg-white/10 text-white font-black text-xl transition-all active:scale-90 border border-white/5">0</button>
            <button 
              onClick={handleSubmit} 
              disabled={pin.length < 4 || isLoading}
              className="h-16 rounded-2xl bg-indigo-600 hover:bg-indigo-700 text-white font-black transition-all active:scale-90 disabled:opacity-50 disabled:grayscale"
            >
              {isLoading ? <i className="fa-solid fa-spinner animate-spin"></i> : <i className="fa-solid fa-arrow-right"></i>}
            </button>
          </div>

          {error && (
            <p className="text-red-400 text-[10px] font-black uppercase text-center tracking-widest animate-bounce">Sandi Salah, Akses Ditolak!</p>
          )}
        </div>

        <p className="text-center mt-8 text-slate-500 text-[9px] font-bold uppercase tracking-widest opacity-50">Authorized Personnel Only</p>
      </div>
    </div>
  );
};

