      </div>
    </div>
  );
};

const DatabaseView: React.FC<DatabaseViewProps> = ({ entries, isLoading, hasError, spreadsheetId, onRefresh, onBack }) => {
  const [search, setSearch] = useState("");
  const [showSetup, setShowSetup] = useState(false);
  const [selectedEntry, setSelectedEntry] = useState<SavedEntry | null>(null);

  const filteredEntries = entries.filter(entry => 
    (entry.nama || "").toLowerCase().includes(search.toLowerCase()) || 
    (entry.nomor_kk || "").toLowerCase().includes(search.toLowerCase()) ||
    (entry.nik || "").toLowerCase().includes(search.toLowerCase())
  );

  const stats = {
    total: entries.length,
    male: entries.filter(e => (e.jenis_kelamin || "").toUpperCase().startsWith('L')).length,
    female: entries.filter(e => (e.jenis_kelamin || "").toUpperCase().startsWith('P')).length
  };

  const handleExportCSV = () => {
    if (entries.length === 0) return;
    const headers = Object.keys(entries[0]).join(",");
    const rows = entries.map(entry => Object.values(entry).map(v => `"${v}"`).join(",")).join("\n");
    const csvContent = "data:text/csv;charset=utf-8," + headers + "\n" + rows;
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `Database_KK_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const appsScriptCode = `function doGet(e) {
  const ssId = e.parameter.spreadsheet_id;
  const action = e.parameter.action;

  if (action === 'check_password') {
    try {
      const ss = SpreadsheetApp.openById(ssId);
      const sheet = ss.getSheetByName("sandi");
      if (!sheet) return ContentService.createTextOutput(JSON.stringify({status: 'error', message: 'Sheet sandi tidak ditemukan'})).setMimeType(ContentService.MimeType.JSON);

      const pwd = e.parameter.password;
      const data = sheet.getDataRange().getValues();
      let isValid = false;
      for (let i = 0; i < data.length; i++) {
        if (data[i][0].toString() === pwd.toString()) {
          isValid = true;
          break;
        }
      }
      return ContentService.createTextOutput(JSON.stringify({status: 'success', valid: isValid})).setMimeType(ContentService.MimeType.JSON);
    } catch (err) {
      return ContentService.createTextOutput(JSON.stringify({status: 'error', message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
    }
  }

  if (action === 'read') {
    try {
      const ss = SpreadsheetApp.openById(ssId);
      const sheet = ss.getSheets()[0]; 
      const data = sheet.getDataRange().getValues();
      const result = [];

      for (let i = 1; i < data.length; i++) {
        const row = data[i];
        if (row[0]) {
          result.push({
            nomor_kk: row[0] ? row[0].toString() : "-",        
            alamat: row[1] ? row[1].toString() : "-",          
