            nama: row[8] ? row[8].toString() : "-",            
            nik: row[9] ? row[9].toString() : "-",             
            jenis_kelamin: row[10] ? row[10].toString() : "-", 
            tempat_lahir: row[11] ? row[11].toString() : "-",  
            tanggal_lahir: row[12] ? row[12].toString() : "-", 
            agama: row[13] ? row[13].toString() : "-",         
            pendidikan: row[14] ? row[14].toString() : "-",    
            jenis_pekerjaan: row[15] ? row[15].toString() : "-",
